<script>
(function(){
  "use strict";
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var fine = window.matchMedia("(hover: hover)").matches;

  /* ---- preloader word ---- */
  var pw = document.getElementById("nc-pword");
  "NOIACORE".split("").forEach(function(ch,i){
    var s=document.createElement("i"); s.textContent=ch; s.style.animationDelay=(0.15+i*0.05)+"s"; pw.appendChild(s);
  });
  window.addEventListener("load", function(){
    setTimeout(function(){ document.getElementById("nc-pre").classList.add("gone"); triggerH1(); }, reduce?300:1700);
  });

  /* ---- clock ---- */
  function tick(){
    var d=new Date();
    function p(n){return (n<10?"0":"")+n;}
    var el=document.getElementById("nc-utc");
    if(el) el.textContent=p(d.getUTCHours())+":"+p(d.getUTCMinutes())+":"+p(d.getUTCSeconds());
  }
  tick(); setInterval(tick,1000);

  /* ---- headline reveal ---- */
  function triggerH1(){ var h=document.getElementById("nc-h1"); if(h) h.classList.add("in"); }

  /* ---- reveal on scroll ---- */
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target);} });
  },{threshold:0.18});
  document.querySelectorAll(".nc-reveal,.nc-clip").forEach(function(el){io.observe(el);});

  /* ---- manifesto word lighting ---- */
  var man=document.getElementById("nc-manifesto");
  if(man){
    var raw=man.innerHTML;
    // wrap plain text words, keep existing spans
    man.innerHTML = raw.replace(/>([^<]+)</g, function(m,txt){
      return ">"+txt.split(/(\s+)/).map(function(w){
        if(/^\s+$/.test(w)) return w;
        return '<span class="nc-w">'+w+'</span>';
      }).join("")+"<";
    });
    var words=Array.prototype.slice.call(man.querySelectorAll(".nc-w"));
    function light(){
      var r=man.getBoundingClientRect();
      var prog=Math.min(1,Math.max(0,(window.innerHeight*0.75 - r.top)/(r.height+window.innerHeight*0.4)));
      var n=Math.floor(prog*words.length);
      words.forEach(function(w,i){ w.classList.toggle("lit", i<n); });
    }
    window.addEventListener("scroll",light,{passive:true}); window.addEventListener("resize",light); light();
  }

  /* ---- cursor + magnetic + grid + emblem + afterimage (single rAF) ---- */
  var dot=document.querySelector(".nc-cdot"), ring=document.querySelector(".nc-cring");
  var mx=innerWidth/2,my=innerHeight/2, dx=mx,dy=my, rx=mx,ry=my;
  var gx=50,gy=50;
  var emblem=document.getElementById("nc-emblem");
  var perc=document.getElementById("nc-perc"), ghost=document.getElementById("nc-ghost");
  var gpx=100,gpy=100, gtx=100,gty=100;

  if(fine && !reduce){
    window.addEventListener("mousemove",function(e){
      mx=e.clientX; my=e.clientY;
      gx=(mx/innerWidth*100); gy=(my/innerHeight*100);
      document.documentElement.style.setProperty("--mx",gx+"%");
      document.documentElement.style.setProperty("--my",gy+"%");

      if(emblem){
        var r=emblem.getBoundingClientRect();
        if(mx>r.left&&mx<r.right&&my>r.top&&my<r.bottom){
          emblem.style.setProperty("--ex",((mx-r.left)/r.width*100)+"%");
          emblem.style.setProperty("--ey",((my-r.top)/r.height*100)+"%");
        }
      }
      if(perc){
        var pr=perc.getBoundingClientRect();
        if(mx>pr.left&&mx<pr.right&&my>pr.top&&my<pr.bottom){
          gtx=80+((mx-pr.left)/pr.width*40); gty=80+((my-pr.top)/pr.height*40);
        } else { gtx=100; gty=100; }
      }
    });

    document.querySelectorAll("a,button,[data-magnetic],.nc-cap,.nc-row,.nc-chip,.nc-terr figure").forEach(function(el){
      el.addEventListener("mouseenter",function(){ document.body.classList.add("nc-hover"); });
      el.addEventListener("mouseleave",function(){ document.body.classList.remove("nc-hover"); el.style.transform=""; });
    });
    document.querySelectorAll("[data-link], .nc-clink a, .nc-word").forEach(function(el){
      el.addEventListener("mouseenter",function(){ document.body.classList.add("nc-link"); });
      el.addEventListener("mouseleave",function(){ document.body.classList.remove("nc-link"); });
    });

    var mags=Array.prototype.slice.call(document.querySelectorAll("[data-magnetic]"));

    function lerp(a,b,t){return a+(b-a)*t;}
    function loop(){
      dx=lerp(dx,mx,0.22); dy=lerp(dy,my,0.22);
      rx=lerp(rx,mx,0.14); ry=lerp(ry,my,0.14);
      if(dot){dot.style.transform="translate("+dx+"px,"+dy+"px)";}
      if(ring){ring.style.transform="translate("+rx+"px,"+ry+"px)";}

      mags.forEach(function(el){
        var r=el.getBoundingClientRect();
        var cx=r.left+r.width/2, cy=r.top+r.height/2;
        var ddx=(mx-cx), ddy=(my-cy);
        var dist=Math.sqrt(ddx*ddx+ddy*ddy);
        if(dist<220){ var f=(1-dist/220)*0.18; el.style.transform="translate("+(ddx*f)+"px,"+(ddy*f)+"px)"; }
        else el.style.transform="";
      });

      if(ghost){ gpx=lerp(gpx,gtx,0.08); gpy=lerp(gpy,gty,0.08); ghost.setAttribute("cx",gpx); ghost.setAttribute("cy",gpy); }

      requestAnimationFrame(loop);
    }
    loop();
  } else {
    // still drive grid mask on touch/scroll-less environments lightly
    document.documentElement.style.setProperty("--mx","50%");
    document.documentElement.style.setProperty("--my","40%");
  }

  /* ---- capability radial follow ---- */
  document.querySelectorAll(".nc-cap").forEach(function(c){
    c.addEventListener("mousemove",function(e){
      var r=c.getBoundingClientRect();
      c.style.setProperty("--cx",((e.clientX-r.left)/r.width*100)+"%");
    });
  });

  /* ---- index active state ---- */
  var secs=Array.prototype.slice.call(document.querySelectorAll("section[id]"));
  var idxLinks=Array.prototype.slice.call(document.querySelectorAll(".nc-index a"));
  var sio=new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(e.isIntersecting){
        idxLinks.forEach(function(a){ a.classList.toggle("on", a.getAttribute("data-i")===e.target.id); });
      }
    });
  },{threshold:0.5});
  secs.forEach(function(s){sio.observe(s);});

})();
</script>
