(function(){
  "use strict";
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var fine = window.matchMedia("(hover: hover)").matches;
  var root = document.documentElement;

  /* preloader word */
  var pw = document.getElementById("nc-pword");
  "NOIACORE".split("").forEach(function(ch,i){
    var s=document.createElement("i"); s.textContent=ch; s.style.animationDelay=(0.15+i*0.05)+"s"; pw.appendChild(s);
  });
  window.addEventListener("load", function(){
    setTimeout(function(){ document.getElementById("nc-pre").classList.add("gone"); var h=document.querySelectorAll("#s1 .nc-reveal"); h.forEach(function(el){el.classList.add("in");}); }, reduce?300:1600);
  });

  /* clock */
  function tick(){
    var d=new Date(); function p(n){return (n<10?"0":"")+n;}
    var el=document.getElementById("nc-utc"); if(el) el.textContent=p(d.getUTCHours())+":"+p(d.getUTCMinutes())+":"+p(d.getUTCSeconds());
  }
  tick(); setInterval(tick,1000);

  /* scroll progress */
  var prog=document.getElementById("nc-prog");
  function onScroll(){
    var h=document.documentElement.scrollHeight-window.innerHeight;
    prog.style.width=(h>0?(window.scrollY/h*100):0)+"%";
  }
  window.addEventListener("scroll",onScroll,{passive:true}); onScroll();

  /* reveal */
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target);} });
  },{threshold:0.16});
  document.querySelectorAll(".nc-reveal").forEach(function(el){ if(!el.closest("#s1")) io.observe(el); });

  /* manifesto word lighting */
  var man=document.getElementById("nc-manifesto");
  if(man){
    man.innerHTML = man.innerHTML.replace(/>([^<]+)</g, function(m,txt){
      return ">"+txt.split(/(\s+)/).map(function(w){ return /^\s+$/.test(w)?w:'<span class="nc-w">'+w+'</span>'; }).join("")+"<";
    });
    var words=Array.prototype.slice.call(man.querySelectorAll(".nc-w"));
    function light(){
      var r=man.getBoundingClientRect();
      var prog2=Math.min(1,Math.max(0,(window.innerHeight*0.78 - r.top)/(r.height+window.innerHeight*0.4)));
      var n=Math.floor(prog2*words.length);
      words.forEach(function(w,i){ w.classList.toggle("lit", i<n); });
    }
    window.addEventListener("scroll",light,{passive:true}); window.addEventListener("resize",light); light();
  }

  /* ===== COSMOS TOGGLE ===== */
  var bNoir=document.getElementById("nc-noir"), bBlanc=document.getElementById("nc-blanc");
  var dustMap={ noir:[244,244,242], blanc:[30,30,42] };
  function setCosmos(c){
    root.setAttribute("data-cosmos",c);
    bNoir.setAttribute("aria-pressed", c==="noir");
    bBlanc.setAttribute("aria-pressed", c==="blanc");
    dustTarget = dustMap[c];
  }
  bNoir.addEventListener("click",function(){setCosmos("noir");});
  bBlanc.addEventListener("click",function(){setCosmos("blanc");});

  /* ===== CANVAS DUST ===== */
  var cv=document.getElementById("nc-canvas"), ctx=cv.getContext("2d");
  var dustRGB=[244,244,242], dustTarget=[244,244,242];
  var parts=[], W=0,H=0,DPR=Math.min(window.devicePixelRatio||1,2);
  function resize(){ W=cv.clientWidth; H=cv.clientHeight; cv.width=W*DPR; cv.height=H*DPR; ctx.setTransform(DPR,0,0,DPR,0,0); buildParts(); }
  function buildParts(){
    var n=Math.round(Math.min(150, W*H/14000)); parts=[];
    for(var i=0;i<n;i++){ parts.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.3+0.2,vx:(Math.random()-.5)*0.12,vy:(Math.random()-.5)*0.12,a:Math.random()*0.5+0.1,tw:Math.random()*Math.PI*2}); }
  }
  resize(); window.addEventListener("resize",resize);
  function lerp(a,b,t){return a+(b-a)*t;}
  function drawDust(){
    ctx.clearRect(0,0,W,H);
    dustRGB[0]=lerp(dustRGB[0],dustTarget[0],0.05);
    dustRGB[1]=lerp(dustRGB[1],dustTarget[1],0.05);
    dustRGB[2]=lerp(dustRGB[2],dustTarget[2],0.05);
    var col=Math.round(dustRGB[0])+","+Math.round(dustRGB[1])+","+Math.round(dustRGB[2]);
    for(var i=0;i<parts.length;i++){
      var p=parts[i];
      p.x+=p.vx; p.y+=p.vy; p.tw+=0.02;
      if(p.x<0)p.x=W; if(p.x>W)p.x=0; if(p.y<0)p.y=H; if(p.y>H)p.y=0;
      var a=p.a*(0.6+0.4*Math.sin(p.tw));
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,6.283); ctx.fillStyle="rgba("+col+","+a.toFixed(3)+")"; ctx.fill();
    }
  }

  /* ===== CURSOR + MAGNETIC + GRID ===== */
  var dot=document.querySelector(".nc-cdot"), ring=document.querySelector(".nc-cring");
  var mx=innerWidth/2,my=innerHeight/2, dx=mx,dy=my, rx=mx,ry=my;
  if(fine && !reduce){
    window.addEventListener("mousemove",function(e){
      mx=e.clientX; my=e.clientY;
      root.style.setProperty("--mx",(mx/innerWidth*100)+"%");
      root.style.setProperty("--my",(my/innerHeight*100)+"%");
    });
    document.querySelectorAll("a,button,[data-magnetic],.nc-cap,.nc-row,.nc-chip,.nc-terr figure,.nc-dual figure").forEach(function(el){
      el.addEventListener("mouseenter",function(){document.body.classList.add("nc-hover");});
      el.addEventListener("mouseleave",function(){document.body.classList.remove("nc-hover");el.style.transform="";});
    });
    document.querySelectorAll("[data-link]").forEach(function(el){
      el.addEventListener("mouseenter",function(){document.body.classList.add("nc-link");});
      el.addEventListener("mouseleave",function(){document.body.classList.remove("nc-link");});
    });
    var mags=Array.prototype.slice.call(document.querySelectorAll("[data-magnetic]"));
    function loop(){
      dx=lerp(dx,mx,0.22); dy=lerp(dy,my,0.22); rx=lerp(rx,mx,0.14); ry=lerp(ry,my,0.14);
      if(dot)dot.style.transform="translate("+dx+"px,"+dy+"px)";
      if(ring)ring.style.transform="translate("+rx+"px,"+ry+"px)";
      mags.forEach(function(el){
        var r=el.getBoundingClientRect(), cx=r.left+r.width/2, cy=r.top+r.height/2;
        var ddx=mx-cx, ddy=my-cy, dist=Math.sqrt(ddx*ddx+ddy*ddy);
        if(dist<240){ var f=(1-dist/240)*0.16; el.style.transform="translate("+(ddx*f)+"px,"+(ddy*f)+"px)"; }
        else if(!el.dataset.locked) el.style.transform="";
      });
      drawDust();
      requestAnimationFrame(loop);
    }
    loop();
  } else {
    (function lp(){ drawDust(); requestAnimationFrame(lp); })();
  }

  /* capability radial follow */
  document.querySelectorAll(".nc-cap").forEach(function(c){
    c.addEventListener("mousemove",function(e){ var r=c.getBoundingClientRect(); c.style.setProperty("--cx",((e.clientX-r.left)/r.width*100)+"%"); });
  });

  /* index active */
  var idxLinks=Array.prototype.slice.call(document.querySelectorAll(".nc-index a"));
  var sio=new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting) idxLinks.forEach(function(a){ a.classList.toggle("on", a.getAttribute("data-i")===e.target.id); }); });
  },{threshold:0.5});
  document.querySelectorAll("section[id]").forEach(function(s){sio.observe(s);});

  /* ===== ILLUSION 01: AFTERIMAGE ===== */
  var aiStage=document.getElementById("aiStage"), aiBtn=document.getElementById("aiBtn"), aiNote=document.getElementById("aiNote");
  var aiTimer=null;
  function aiReveal(){
    aiStage.classList.add("revealed");
    aiBtn.textContent="Reiniciar estímulo";
    aiNote.textContent="Mira el centro del blanco: aparece el cuadrado complementario.";
  }
  function aiReset(){
    aiStage.classList.remove("revealed");
    aiBtn.textContent="Revelar postimagen";
    aiNote.textContent="Fija la mirada en el punto. No la muevas.";
  }
  aiBtn.addEventListener("click",function(){ aiStage.classList.contains("revealed")?aiReset():aiReveal(); });

  /* ===== ILLUSION 02: FIGURE-GROUND ===== */
  var fgStage=document.getElementById("fgStage"), fgBtn=document.getElementById("fgBtn"), fgCap=document.getElementById("fgCap");
  fgBtn.addEventListener("click",function(){
    var inv=fgStage.classList.toggle("inv");
    fgCap.textContent = inv ? "Ahora el fondo es figura: aparecen dos rostros de perfil mirándose." : "Rubin, 1915. Tu cerebro no puede ver ambas a la vez: alterna.";
  });

})();
</script>
