.nc-logo b{width:5px;height:5px;background:var(--accent-h);display:inline-block;animation:nc-blink 3s ease-in-out infinite}
.nc-topr{display:flex;align-items:center;gap:30px}
.nc-clock{font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--ink);opacity:.5}
.nc-cta{font-family:var(--mono);font-size:10px;letter-spacing:.28em;text-transform:uppercase;color:var(--ink);position:relative;padding-bottom:4px}
.nc-cta::after{content:"";position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--accent-h);transform:scaleX(0);transform-origin:right;transition:transform .55s var(--ease)}
.nc-cta:hover::after{transform:scaleX(1);transform-origin:left}
@keyframes nc-blink{0%,100%{opacity:1}50%{opacity:.25}}
@media(max-width:640px){.nc-clock{display:none}}

/* vertical rail */
.nc-rail{position:fixed;right:clamp(16px,2.4vw,40px);top:50%;transform:translateY(-50%);z-index:290;height:38vh;width:1px;background:var(--line)}
.nc-rail .nc-fill{position:absolute;top:0;left:0;width:1px;height:100%;background:var(--accent);transform-origin:top;transform:scaleY(0)}
.nc-rail a{position:absolute;left:0;width:24px;height:24px;margin-left:-12px;transform:translateY(-50%);display:flex;align-items:center;justify-content:center}
.nc-rail .nc-tk{width:5px;height:5px;border:1px solid var(--muted);background:var(--black);transition:border-color .4s var(--ease),background .4s var(--ease),transform .4s var(--ease)}
.nc-rail a.on .nc-tk{border-color:var(--accent-h);background:var(--accent-h);transform:scale(1.4)}
.nc-rail .nc-rl{position:absolute;right:22px;font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted);white-space:nowrap;opacity:0;transform:translateX(6px);transition:opacity .4s var(--ease),transform .4s var(--ease);pointer-events:none}
.nc-rail a:hover .nc-rl,.nc-rail a.on .nc-rl{opacity:1;transform:none}
@media(max-width:900px){.nc-rail{display:none}}

/* ===================== LAYOUT ===================== */
main{position:relative;z-index:1}
section{position:relative}
.nc-pad{padding-left:clamp(20px,5vw,72px);padding-right:clamp(20px,5vw,72px)}
.nc-wrap{width:100%;max-width:var(--maxw);margin:0 auto}
.nc-num{font-family:var(--mono);font-size:11px;letter-spacing:.34em;color:var(--muted);text-transform:uppercase;display:flex;align-items:center;gap:14px}
.nc-num::before{content:"";width:30px;height:1px;background:var(--accent)}
.nc-rule{height:1px;width:100%;background:var(--line);transform:scaleX(0);transform-origin:center}

.ln{display:block;overflow:hidden;padding-bottom:.1em}
.ln>i{display:block;font-style:normal;will-change:transform}

/* ===================== PRELOADER ===================== */
#nc-pre{position:fixed;inset:0;z-index:700;background:var(--void);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:30px}
#nc-pre .nc-pbar{width:min(42vw,240px);height:1px;background:var(--line);position:relative;overflow:hidden}
#nc-pre .nc-pbar i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(0)}
#nc-pre .nc-pword{font-family:var(--mono);font-size:11px;letter-spacing:.62em;color:var(--muted);opacity:0}
#nc-pre .nc-pct{font-family:var(--display);font-weight:800;font-size:13px;letter-spacing:.1em;color:var(--ink-hi);opacity:0}

/* ===================== S0 HERO ===================== */
#s0{min-height:100vh;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:130px 0 90px;position:relative;overflow:hidden}
.nc-beam{position:absolute;left:50%;top:0;width:1px;height:100%;transform:translateX(-50%);background:linear-gradient(transparent,rgba(218,218,210,.10) 30%,rgba(218,218,210,.10) 70%,transparent);pointer-events:none}
.nc-hud{position:absolute;font-family:var(--mono);font-size:10px;letter-spacing:.22em;color:var(--muted);line-height:2.1;opacity:0}
.nc-hud.tl{top:clamp(90px,13vh,140px);left:clamp(20px,5vw,72px);text-align:left}
.nc-hud.tr{top:clamp(90px,13vh,140px);right:clamp(20px,5vw,72px);text-align:right}
.nc-hud.bl{bottom:clamp(74px,11vh,120px);left:clamp(20px,5vw,72px)}
.nc-hud.br{bottom:clamp(74px,11vh,120px);right:clamp(20px,5vw,72px);text-align:right}
.nc-hud em{color:var(--ink);font-style:normal}
.nc-emblem{position:relative;width:clamp(130px,19vw,220px);aspect-ratio:1;margin-bottom:clamp(36px,6vh,66px)}
.nc-emblem svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.nc-emblem .draw{fill:none;stroke:var(--ink);stroke-width:.5;opacity:.6}
.nc-emblem .draw.d{stroke:var(--muted);opacity:.45}
.nc-emblem .tick{stroke:var(--muted);stroke-width:.5}
.nc-emblem .core{fill:var(--accent)}
.nc-emblem .halo{fill:none;stroke:var(--accent);stroke-width:.4;opacity:.45}
.nc-emblem .inv{position:absolute;inset:0;opacity:0;transition:opacity .5s var(--ease);
  -webkit-mask-image:radial-gradient(60px circle at var(--ex,50%) var(--ey,50%),#000 25%,transparent 72%);
  mask-image:radial-gradient(60px circle at var(--ex,50%) var(--ey,50%),#000 25%,transparent 72%);}
.nc-emblem:hover .inv{opacity:1}
.nc-emblem .inv svg .draw{stroke:var(--black)}
.nc-emblem .inv svg .core{fill:var(--accent-d)}
.nc-emblem .inv{background:var(--ink-hi);border-radius:50%}
.nc-word{font-family:var(--sans);font-weight:200;font-size:clamp(2.6rem,11.5vw,9.8rem);letter-spacing:.34em;text-indent:.34em;line-height:.9;color:var(--ink-hi)}
.nc-tag{font-family:var(--human);font-style:italic;font-weight:300;font-size:clamp(1.05rem,2.3vw,1.7rem);color:var(--muted);margin-top:clamp(20px,3vh,34px);font-variation-settings:"opsz" 60}
.nc-tag em{color:var(--ink);font-style:italic}
.nc-cue{position:absolute;left:50%;bottom:30px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:12px;font-family:var(--mono);font-size:9px;letter-spacing:.34em;color:var(--muted);opacity:0}
.nc-cue .nc-bar{width:1px;height:46px;background:linear-gradient(var(--accent),transparent);transform-origin:top;animation:nc-drip 2.8s var(--ease) infinite}
@keyframes nc-drip{0%{transform:scaleY(.12)}45%{transform:scaleY(1)}55%{transform:scaleY(1);transform-origin:bottom}100%{transform:scaleY(.12);transform-origin:bottom}}
@media(max-width:780px){.nc-hud{display:none}}

/* ===================== S1 MANIFESTO ===================== */
#s1{padding:clamp(130px,20vh,240px) 0}
.nc-man{font-family:var(--display);font-weight:700;font-size:clamp(1.7rem,5.6vw,5rem);line-height:1.1;letter-spacing:-.02em;max-width:20ch;color:var(--ink-hi)}
.nc-man .w{opacity:.14;transition:opacity .2s linear}
.nc-man .w.lit{opacity:1}
.nc-man .w.red{color:var(--accent-h)}
.nc-mansrc{font-family:var(--mono);font-size:11px;letter-spacing:.24em;color:var(--muted);margin-top:44px}

/* ===================== S2 BUILD (pinned) ===================== */
#s2{background:var(--void)}
.nc-build{height:100vh;display:flex;align-items:center}
.nc-bgrid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(30px,6vw,90px);align-items:center;width:100%}
.nc-bcopy .nc-num{margin-bottom:34px}
.nc-bstage{position:relative;height:clamp(200px,30vh,300px)}
.nc-bphrase{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;opacity:0;will-change:transform,opacity}
.nc-bphrase h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,5.4vw,4.4rem);line-height:1;letter-spacing:-.02em;color:var(--ink-hi)}
.nc-bphrase h2 em{font-style:normal;color:var(--accent-h)}
.nc-bphrase p{font-family:var(--mono);font-size:12px;letter-spacing:.04em;color:var(--muted);margin-top:20px;max-width:34ch;line-height:1.75}
.nc-bsteps{list-style:none;display:flex;gap:28px;margin-top:38px}
.nc-bsteps li{font-family:var(--mono);font-size:10px;letter-spacing:.22em;color:var(--muted);display:flex;align-items:center;gap:10px;transition:color .5s var(--ease)}
.nc-bsteps li::before{content:"";width:14px;height:1px;background:var(--muted);transition:background .5s var(--ease),width .5s var(--ease)}
.nc-bsteps li.on{color:var(--ink)}
.nc-bsteps li.on::before{background:var(--accent-h);width:28px}
.nc-bvisual{display:flex;justify-content:center;align-items:center}
.nc-bemblem{width:clamp(230px,32vw,420px);aspect-ratio:1}
.nc-bemblem svg{width:100%;height:100%;overflow:visible}
.nc-bemblem .mod{fill:var(--ink)}
.nc-bemblem .mod.dim{fill:var(--muted)}
.nc-bemblem .core{fill:var(--accent)}
@media(max-width:840px){
  .nc-bgrid{grid-template-columns:1fr;gap:40px}
  .nc-build{height:auto;min-height:100vh;padding:120px 0;flex-direction:column}
  .nc-bvisual{order:-1}
  .nc-bstage{height:auto;position:static}
  .nc-bphrase{position:static;opacity:1!important;transform:none!important}
  .nc-bphrase:not(:first-child){display:none}
}

/* ===================== S3 HARMONY ===================== */
#s3{padding:clamp(120px,18vh,220px) 0}
.nc-harm-head{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-bottom:clamp(40px,7vh,80px)}
.nc-harm-head h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,5.6vw,4.6rem);line-height:.98;letter-spacing:-.02em;color:var(--ink-hi);max-width:13ch}
.nc-harm-head h2 em{font-style:normal;color:var(--accent-h)}
.nc-harm-head p{font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--muted);max-width:30ch;text-align:right}
.nc-prop{display:flex;height:70px;border:1px solid var(--line);overflow:hidden}
.nc-prop .nc-seg{display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-size:10px;letter-spacing:.22em;transition:flex-basis .6s var(--ease);overflow:hidden;white-space:nowrap}
.nc-prop .s70{flex-basis:70;background:var(--panel);color:var(--muted)}
.nc-prop .s20{flex-basis:20;background:var(--ink);color:var(--black)}
.nc-prop .s10{flex-basis:10;background:var(--accent);color:var(--ink-hi);position:relative}
.nc-prop .s10 .rv{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .4s var(--ease);font-size:9px}
.nc-prop .s10:hover{flex-basis:26}
.nc-prop .s10:hover .rv{opacity:1}
.nc-chips{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-top:none}
.nc-chip{background:var(--black);padding:26px 20px 30px;min-height:184px;display:flex;flex-direction:column;justify-content:space-between;transition:background .5s var(--ease)}
.nc-chip:hover{background:var(--panel)}
.nc-chip .sw{width:32px;height:32px;border:1px solid var(--line)}
.nc-chip h4{font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;font-weight:500;color:var(--ink)}
.nc-chip .hex{font-family:var(--mono);font-size:10px;color:var(--muted);margin-top:5px}
.nc-chip p{font-size:12.5px;color:var(--muted);line-height:1.55;margin-top:9px}
@media(max-width:880px){.nc-chips{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.nc-chips{grid-template-columns:1fr}.nc-prop .nc-seg{font-size:8px}}

/* ===================== S4 CAPABILITIES ===================== */
#s4{padding:clamp(110px,16vh,180px) 0}
.nc-cap-head{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-bottom:clamp(40px,7vh,80px)}
.nc-cap-head h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,5.8vw,4.8rem);line-height:.96;letter-spacing:-.02em;color:var(--ink-hi);max-width:12ch}
.nc-cap-head h2 em{font-style:normal;color:var(--accent-h)}
.nc-cap-head p{font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--muted);max-width:28ch;text-align:right}
.nc-caps{border-top:1px solid var(--line)}
.nc-cap{position:relative;display:grid;grid-template-columns:60px 1fr auto;align-items:center;gap:clamp(12px,3vw,38px);padding:clamp(20px,3vh,34px) 4px;border-bottom:1px solid var(--line);overflow:hidden;transition:padding .5s var(--ease)}
.nc-cap::before{content:"";position:absolute;inset:0;background:radial-gradient(120% 140% at var(--cx,50%) 50%,rgba(142,20,48,.16),transparent 60%);opacity:0;transition:opacity .4s var(--ease)}
.nc-cap:hover::before{opacity:1}
.nc-cap:hover{padding-left:clamp(20px,3vw,40px)}
.nc-cap .cn{font-family:var(--mono);font-size:11px;letter-spacing:.1em;color:var(--muted);position:relative;z-index:1}
.nc-cap .cx{font-family:var(--display);font-weight:700;font-size:clamp(1.3rem,3.4vw,2.7rem);letter-spacing:-.01em;line-height:1;color:var(--muted);position:relative;z-index:1;transition:color .5s var(--ease),transform .5s var(--ease)}
.nc-cap:hover .cx{color:var(--ink-hi);transform:translateX(6px)}
.nc-cap .cg{font-family:var(--mono);font-size:11px;letter-spacing:.04em;color:var(--muted);position:relative;z-index:1;opacity:0;transform:translateX(-8px);transition:opacity .5s var(--ease),transform .5s var(--ease)}
.nc-cap .ca{font-family:var(--mono);color:var(--accent-h);position:relative;z-index:1;opacity:0;transform:translateX(-8px);transition:opacity .5s var(--ease),transform .5s var(--ease)}
.nc-cap:hover .cg,.nc-cap:hover .ca{opacity:1;transform:none}
@media(max-width:760px){.nc-cap{grid-template-columns:46px 1fr}.nc-cap .cg,.nc-cap .ca{display:none}}

/* ===================== S5 LAB ===================== */
#s5{padding:clamp(120px,18vh,220px) 0;background:var(--void)}
.nc-lab-head{display:grid;grid-template-columns:1.2fr .8fr;gap:clamp(28px,5vw,76px);align-items:end;margin-bottom:clamp(40px,7vh,80px)}
.nc-lab-head h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,6.2vw,5.2rem);line-height:.94;letter-spacing:-.02em;text-transform:uppercase;color:var(--ink-hi)}
.nc-lab-head h2 em{font-style:normal;-webkit-text-stroke:1px var(--ink-hi);color:transparent}
.nc-lab-head p{color:var(--ink);font-size:clamp(1rem,1.5vw,1.18rem);max-width:38ch}
.nc-lab-head p b{color:var(--accent-h);font-weight:400}
.nc-term{border:1px solid var(--line);background:var(--panel);position:relative;overflow:hidden}
.nc-term::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent,rgba(142,20,48,.04));pointer-events:none;mix-blend-mode:screen}
.nc-term-bar{display:flex;align-items:center;gap:8px;padding:13px 18px;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--muted)}
.nc-term-bar i{width:8px;height:8px;border-radius:50%;background:var(--muted);display:inline-block}
.nc-term-bar i:first-child{background:var(--accent-h)}
.nc-term-bar .tt{margin-left:auto;color:var(--ink)}
.nc-rows{list-style:none}
.nc-row{display:grid;grid-template-columns:76px 1fr 86px 20px;align-items:center;gap:14px;padding:12px 18px;border-bottom:1px solid var(--line-2);font-family:var(--mono);font-size:12px;letter-spacing:.03em;transition:background .3s var(--ease),padding-left .3s var(--ease)}
.nc-row:last-child{border-bottom:none}
.nc-row:hover{background:rgba(142,20,48,.08);padding-left:26px}
.nc-row .rid{color:var(--muted)}
.nc-row .rn{color:var(--ink);transition:color .3s var(--ease)}
.nc-row:hover .rn{color:var(--ink-hi)}
.nc-row .rs{font-size:10px;letter-spacing:.16em;text-align:right}
.nc-row .rs.live{color:var(--accent-h)}
.nc-row .rs.beta{color:var(--ink)}
.nc-row .rs.soon{color:var(--muted)}
.nc-row .rd{width:6px;height:6px;border-radius:50%;background:var(--muted);justify-self:end}
.nc-row .rd.live{background:var(--accent-h);box-shadow:0 0 8px var(--accent-h);animation:nc-blink 2.4s ease-in-out infinite}
.nc-lab-foot{margin-top:24px;font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--muted);display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}
@media(max-width:760px){.nc-lab-head{grid-template-columns:1fr}.nc-row{grid-template-columns:60px 1fr 60px}.nc-row .rd{display:none}}

/* ===================== S6 PERCEPTION ===================== */
#s6{padding:clamp(120px,18vh,220px) 0}
.nc-perc-intro{max-width:24ch;margin-bottom:clamp(40px,7vh,80px)}
.nc-perc-intro h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,6vw,5rem);line-height:.96;letter-spacing:-.02em;color:var(--ink-hi)}
.nc-perc-intro h2 em{font-style:normal;color:var(--accent-h)}
.nc-perc-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(20px,3vw,40px)}
.nc-ill{border:1px solid var(--line);background:var(--panel);padding:clamp(24px,3vw,40px);display:flex;flex-direction:column;gap:22px}
.nc-ill .ik{font-family:var(--mono);font-size:10px;letter-spacing:.28em;color:var(--accent-h);text-transform:uppercase}
.nc-ill h3{font-family:var(--display);font-weight:700;font-size:clamp(1.3rem,2.6vw,2rem);letter-spacing:-.01em;line-height:1.06;color:var(--ink-hi)}
.nc-ill p{font-size:13px;color:var(--muted);line-height:1.65;max-width:44ch}
/* afterimage */
.nc-ai{position:relative;aspect-ratio:16/10;border:1px solid var(--line);overflow:hidden;display:grid;place-items:center}
.nc-ai .stim,.nc-ai .neut{position:absolute;inset:0;display:grid;place-items:center;transition:opacity .2s linear}
.nc-ai .stim{background:#00b3c4}
.nc-ai .stim .sq{width:34%;aspect-ratio:1;background:#d4202f}
.nc-ai .stim .fix{position:absolute;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.3)}
.nc-ai .neut{background:#8a8a8a;opacity:0}
.nc-ai .neut .fix{width:6px;height:6px;border-radius:50%;background:#111}
.nc-ai.on .stim{opacity:0}
.nc-ai.on .neut{opacity:1}
.nc-ctrl{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.nc-btn{font-family:var(--mono);font-size:11px;letter-spacing:.18em;text-transform:uppercase;padding:12px 22px;border:1px solid var(--line);color:var(--ink);transition:background .35s var(--ease),color .35s var(--ease),border-color .35s var(--ease)}
.nc-btn:hover{background:var(--accent);border-color:var(--accent);color:var(--ink-hi)}
.nc-note{font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--muted)}
/* rubin */
.nc-rubin{position:relative;aspect-ratio:16/10;border:1px solid var(--line);overflow:hidden}
.nc-rubin svg{position:absolute;inset:0;width:100%;height:100%}
.nc-rubin .lay{position:absolute;inset:0}
.nc-rubin .fig{fill:var(--ink)}
.nc-rubin .gnd{fill:var(--black)}
.nc-rubin .lay.b{opacity:0}
.nc-rubin .lay.b .fig{fill:var(--black)}
.nc-rubin .lay.b .gnd{fill:var(--ink)}
.nc-rubcap{font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--muted);text-align:center;min-height:2.4em}
@media(max-width:820px){.nc-perc-grid{grid-template-columns:1fr}}

/* ===================== S7 SIGNAL ===================== */
#s7{padding:clamp(120px,18vh,220px) 0;text-align:center;background:var(--void)}
.nc-sig-k{font-family:var(--mono);font-size:11px;letter-spacing:.34em;color:var(--muted);text-transform:uppercase}
.nc-sig-val{font-family:var(--display);font-weight:800;font-size:clamp(5rem,26vw,22rem);line-height:.82;letter-spacing:-.05em;color:var(--ink-hi);margin:clamp(16px,3vh,34px) 0}
.nc-sig-val .su{color:var(--accent-h);font-size:.3em;vertical-align:super;margin-left:.04em}
.nc-sig-line{font-family:var(--human);font-style:italic;font-weight:300;font-size:clamp(1.1rem,2.4vw,1.7rem);color:var(--muted);max-width:26ch;margin:0 auto;font-variation-settings:"opsz" 60}
.nc-sig-line em{color:var(--ink);font-style:italic}
.nc-stats{display:flex;justify-content:center;gap:clamp(30px,7vw,90px);margin-top:clamp(70px,12vh,130px);flex-wrap:wrap}
.nc-stat{position:relative;text-align:left;max-width:230px;padding-left:clamp(20px,3vw,40px)}
.nc-stat::before{content:"";position:absolute;left:0;top:6px;bottom:6px;width:1px;background:var(--line)}
.nc-stat .sv{font-family:var(--display);font-weight:800;font-size:clamp(2.4rem,5vw,4rem);line-height:.9;letter-spacing:-.03em;color:var(--ink-hi)}
.nc-stat .sv .su{color:var(--accent-h);font-size:.42em;vertical-align:super}
.nc-stat .sk{font-family:var(--mono);font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--muted);margin-top:14px}
.nc-stat .sd{font-size:13px;color:var(--muted);line-height:1.55;margin-top:8px}

/* ===================== S8 TERRITORIES (asymmetric mosaic) ===================== */
#s8{padding:clamp(120px,18vh,220px) 0}
.nc-terr-head{margin-bottom:clamp(40px,7vh,80px)}
.nc-terr-head h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,6vw,5rem);line-height:.96;letter-spacing:-.02em;color:var(--ink-hi);max-width:14ch}
.nc-terr-head h2 em{font-style:normal;color:var(--accent-h)}
.nc-mosaic{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:minmax(150px,auto);gap:1px;background:var(--line);border:1px solid var(--line)}
.nc-mosaic figure{background:var(--black);padding:clamp(26px,3.4vw,48px);position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between;transition:background .55s var(--ease)}
.nc-mosaic figure:hover{background:var(--panel)}
.nc-mosaic figure::after{content:attr(data-n);position:absolute;right:18px;bottom:12px;font-family:var(--display);font-weight:800;font-size:clamp(3rem,7vw,6rem);line-height:1;color:var(--line-2);transition:color .55s var(--ease)}
.nc-mosaic figure:hover::after{color:var(--line)}
.nc-mosaic .tk{font-family:var(--mono);font-size:10px;letter-spacing:.24em;color:var(--accent-h);text-transform:uppercase;position:relative;z-index:1}
.nc-mosaic h3{font-family:var(--display);font-weight:700;font-size:clamp(1.3rem,2.6vw,2.1rem);letter-spacing:-.01em;line-height:1.05;color:var(--ink-hi);position:relative;z-index:1;max-width:14ch}
.nc-mosaic p{font-size:13px;color:var(--muted);line-height:1.55;position:relative;z-index:1;max-width:32ch}
.nc-mosaic .f1{grid-column:1 / 3;grid-row:1 / 3}
.nc-mosaic .f2{grid-column:3 / 4;grid-row:1 / 2}
.nc-mosaic .f3{grid-column:3 / 4;grid-row:2 / 3}
.nc-mosaic .f4{grid-column:1 / 4;grid-row:3 / 4;flex-direction:row;align-items:center;justify-content:space-between;gap:30px}
.nc-mosaic .f4 h3{max-width:18ch}
.nc-mosaic .f4 p{max-width:40ch}
@media(max-width:820px){
  .nc-mosaic{grid-template-columns:1fr}
  .nc-mosaic .f1,.nc-mosaic .f2,.nc-mosaic .f3,.nc-mosaic .f4{grid-column:1;grid-row:auto}
  .nc-mosaic .f4{flex-direction:column;align-items:flex-start}
}

/* ===================== S9 CONTACT ===================== */
#s9{padding:clamp(130px,20vh,240px) 0 clamp(70px,10vh,120px);background:var(--void)}
.nc-con{display:flex;flex-direction:column;gap:clamp(34px,6vh,70px)}
.nc-con h2{font-family:var(--display);font-weight:800;font-size:clamp(2.6rem,11vw,9.5rem);line-height:.9;letter-spacing:-.03em;color:var(--ink-hi)}
.nc-con h2 em{font-style:normal;color:var(--accent-h)}
.nc-clinks{display:flex;flex-wrap:wrap;gap:clamp(34px,8vw,120px);align-items:flex-end}
.nc-clink{display:flex;flex-direction:column;gap:12px}
.nc-clink .ck{font-family:var(--mono);font-size:10px;letter-spacing:.26em;color:var(--muted);text-transform:uppercase}
.nc-clink a{font-family:var(--display);font-weight:700;font-size:clamp(1.2rem,3.2vw,2.4rem);letter-spacing:-.01em;position:relative;width:max-content;color:var(--ink);transition:color .4s var(--ease)}
.nc-clink a::after{content:"";position:absolute;left:0;bottom:-3px;width:100%;height:1px;background:var(--accent-h);transform:scaleX(0);transform-origin:right;transition:transform .55s var(--ease)}
.nc-clink a:hover{color:var(--ink-hi)}
.nc-clink a:hover::after{transform:scaleX(1);transform-origin:left}
.nc-con-note{font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--muted);max-width:48ch}

footer{position:relative;z-index:1;border-top:1px solid var(--line);padding:28px clamp(20px,5vw,72px);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--muted)}
footer .fm{display:flex;align-items:center;gap:11px;color:var(--ink)}
footer .fm svg{width:15px;height:15px}
footer .fm .a{fill:var(--ink)}
footer .fm .c{fill:var(--accent-h)}

@media(prefers-reduced-motion:reduce){
  .nc-glow,.nc-grain,.nc-cue .nc-bar,.nc-logo b,.nc-row .rd.live{animation:none}
  .ln>i{transform:none!important}
}
</style>
</head>
