        <circle class="core" id="emCore" cx="50" cy="50" r="6"/>
      </svg>
      <div class="inv" aria-hidden="true">
        <svg viewBox="0 0 100 100">
          <circle class="halo draw" cx="50" cy="50" r="46"/>
          <ellipse class="draw" cx="50" cy="50" rx="40" ry="17" transform="rotate(26 50 50)"/>
          <ellipse class="draw" cx="50" cy="50" rx="40" ry="17" transform="rotate(-34 50 50)"/>
