.nc-chip h4{font-family:var(--mono);font-size:10px;letter-spacing:.18em;text-transform:uppercase;font-weight:500}
.nc-chip .nc-hex{font-family:var(--mono);font-size:10px;color:var(--muted);margin-top:4px}
.nc-chip p{font-size:12.5px;color:var(--muted);line-height:1.5;margin-top:8px}
@media(max-width:880px){.nc-chips{grid-template-columns:repeat(2,1fr)}.nc-prop .nc-seg{font-size:8px}}
@media(max-width:480px){.nc-chips{grid-template-columns:1fr}}

/* ============ S4 CAPABILITIES ============ */
.nc-cap-intro{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-bottom:clamp(34px,6vh,66px)}
.nc-cap-intro h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,5.8vw,4.8rem);line-height:.95;letter-spacing:-.02em;text-transform:uppercase;max-width:12ch}
.nc-cap-intro p{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--muted);max-width:30ch;text-align:right}
.nc-caps{border-top:1px solid var(--line)}
.nc-cap{position:relative;display:grid;grid-template-columns:60px 1fr auto;align-items:center;gap:clamp(14px,3vw,38px);padding:clamp(18px,3vh,34px) 8px;border-bottom:1px solid var(--line);cursor:none;overflow:hidden;transition:padding .4s var(--ease)}
.nc-cap::before{content:"";position:absolute;inset:0;background:radial-gradient(120% 140% at var(--cx,50%) 50%,rgba(122,14,26,.16),transparent 60%);opacity:0;transition:opacity .4s var(--ease)}
.nc-cap:hover::before{opacity:1}
.nc-cap:hover{padding-left:clamp(26px,4vw,52px)}
.nc-cap .nc-num{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--muted);position:relative;z-index:1}
.nc-cap .nc-name{font-family:var(--display);font-weight:700;font-size:clamp(1.3rem,3.4vw,2.8rem);letter-spacing:-.01em;line-height:1;position:relative;z-index:1;color:var(--ink2);transition:transform .4s var(--ease),color .4s var(--ease)}
.nc-cap:hover .nc-name{transform:translateX(8px);color:var(--ink)}
.nc-cap .nc-gloss{font-family:var(--mono);font-size:12px;letter-spacing:.05em;color:var(--muted);max-width:0;opacity:0;white-space:nowrap;overflow:hidden;transition:max-width .5s var(--ease),opacity .4s var(--ease);position:relative;z-index:1}
.nc-cap:hover .nc-gloss{max-width:40ch;opacity:1}
.nc-cap .nc-arrow{font-family:var(--mono);color:var(--accent-h);opacity:0;transform:translateX(-8px);transition:opacity .4s var(--ease),transform .4s var(--ease);position:relative;z-index:1}
.nc-cap:hover .nc-arrow{opacity:1;transform:none}
@media(max-width:760px){.nc-cap{grid-template-columns:42px 1fr}.nc-cap .nc-gloss,.nc-cap .nc-arrow{display:none}}

/* ============ S5 LAB TERMINAL ============ */
.nc-lab-head{display:grid;grid-template-columns:1.2fr .8fr;gap:clamp(28px,5vw,76px);align-items:end;margin-bottom:clamp(38px,7vh,76px)}
.nc-lab-head h2{font-family:var(--display);font-weight:800;font-size:clamp(2rem,6.2vw,5.2rem);line-height:.94;letter-spacing:-.02em;text-transform:uppercase}
.nc-lab-head h2 .nc-out{-webkit-text-stroke:1px var(--ink);color:transparent}
.nc-lab-head p{color:var(--ink2);font-size:clamp(1rem,1.5vw,1.18rem);max-width:38ch}
.nc-lab-head p b{color:var(--accent-h);font-weight:500}
.nc-term{border:1px solid var(--line);background:var(--bg2)}
.nc-term-bar{display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--line);font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--muted)}
.nc-term-bar i{width:8px;height:8px;border-radius:50%;background:var(--muted);display:inline-block}
.nc-term-bar i:first-child{background:var(--accent-h)}
.nc-term-bar .nc-tt{margin-left:auto;color:var(--ink2)}
.nc-rows{list-style:none}
.nc-row{display:grid;grid-template-columns:74px 1fr 88px 20px;align-items:center;gap:14px;padding:12px 16px;border-bottom:1px solid var(--line2);font-family:var(--mono);font-size:12px;letter-spacing:.03em;transition:background .3s var(--ease),padding-left .3s var(--ease)}
.nc-row:last-child{border-bottom:none}
.nc-row:hover{background:rgba(122,14,26,.08);padding-left:24px}
.nc-row .nc-rid{color:var(--muted)}
.nc-row .nc-rname{color:var(--ink2);transition:color .3s var(--ease)}
.nc-row:hover .nc-rname{color:var(--ink)}
.nc-row .nc-rst{font-size:10px;letter-spacing:.16em;text-align:right}
.nc-row .nc-rst.live{color:var(--accent-h)}
.nc-row .nc-rst.beta{color:var(--ink2)}
.nc-row .nc-rst.soon{color:var(--muted)}
.nc-row .nc-rdot{width:6px;height:6px;border-radius:50%;background:var(--muted);justify-self:end}
.nc-row .nc-rdot.live{background:var(--accent-h);box-shadow:0 0 8px var(--accent-h);animation:nc-blink 2.4s ease-in-out infinite}
@keyframes nc-blink{0%,100%{opacity:1}50%{opacity:.3}}
.nc-lab-foot{margin-top:22px;font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--muted);display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}
@media(max-width:760px){.nc-lab-head{grid-template-columns:1fr}.nc-row{grid-template-columns:58px 1fr 60px}.nc-row .nc-rdot{display:none}}

/* ============ S6 PERCEPTION / ILLUSIONS ============ */
.nc-perc-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(20px,3vw,40px);margin-top:clamp(36px,6vh,70px)}
.nc-ill{border:1px solid var(--line);background:var(--bg2);padding:clamp(22px,3vw,38px);display:flex;flex-direction:column;gap:20px}
.nc-ill .nc-illk{font-family:var(--mono);font-size:10px;letter-spacing:.26em;color:var(--accent-h);text-transform:uppercase}
.nc-ill h3{font-family:var(--display);font-weight:700;font-size:clamp(1.3rem,2.6vw,2rem);letter-spacing:-.01em;line-height:1.05}
.nc-ill p{font-size:13.5px;color:var(--muted);line-height:1.6;max-width:42ch}
/* afterimage */
.nc-ai-stage{position:relative;aspect-ratio:16/9;border:1px solid var(--line);overflow:hidden;display:grid;place-items:center}
.nc-ai-stim,.nc-ai-neutral{position:absolute;inset:0;display:grid;place-items:center;transition:opacity .25s linear}
.nc-ai-stim{background:#13b6c9}
.nc-ai-stim .nc-ai-sq{width:34%;aspect-ratio:1;background:#e0243a}
.nc-ai-stim .nc-ai-fix{position:absolute;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.3)}
.nc-ai-neutral{background:var(--bg);opacity:0}
.nc-ai-neutral .nc-ai-fix{width:6px;height:6px;border-radius:50%;background:var(--muted)}
.nc-ai-stage.revealed .nc-ai-stim{opacity:0}
.nc-ai-stage.revealed .nc-ai-neutral{opacity:1}
.nc-ai-ctrl{display:flex;align-items:center;gap:16px;flex-wrap:wrap}
.nc-btn{font-family:var(--mono);font-size:11px;letter-spacing:.18em;text-transform:uppercase;padding:11px 20px;border:1px solid var(--line);color:var(--ink);transition:background .3s var(--ease),color .3s var(--ease),border-color .3s var(--ease)}
.nc-btn:hover{background:var(--accent);border-color:var(--accent);color:#fff}
.nc-ai-note{font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--muted)}
/* figure-ground */
.nc-fg-stage{position:relative;aspect-ratio:16/9;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden;--fig:var(--ink);--gnd:var(--bg2);background:var(--gnd);transition:background .4s var(--ease)}
.nc-fg-stage.inv{--fig:var(--bg2);--gnd:var(--ink)}
.nc-fg-stage svg{width:62%;height:84%}
.nc-fg-stage .nc-vase{fill:var(--fig);transition:fill .4s var(--ease)}
.nc-fg-cap{font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:var(--muted);text-align:center}
@media(max-width:820px){.nc-perc-grid{grid-template-columns:1fr}}

/* ============ S7 TERRITORIES ============ */
.nc-terr{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border:1px solid var(--line);margin-top:clamp(38px,7vh,76px)}
.nc-terr figure{background:var(--bg);padding:clamp(28px,5vw,60px);min-height:clamp(210px,28vh,320px);display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden;transition:background .5s var(--ease)}
.nc-terr figure:hover{background:var(--bg2)}
.nc-terr figure::after{content:attr(data-n);position:absolute;right:18px;bottom:14px;font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--line)}
.nc-terr h3{font-family:var(--display);font-weight:700;font-size:clamp(1.4rem,3vw,2.4rem);letter-spacing:-.01em;line-height:1.04;max-width:13ch}
.nc-terr p{font-size:14px;color:var(--muted);max-width:34ch;line-height:1.55}
.nc-terr .nc-tk{font-family:var(--mono);font-size:11px;letter-spacing:.2em;color:var(--accent-h);text-transform:uppercase}
@media(max-width:760px){.nc-terr{grid-template-columns:1fr}}

/* ============ S8 CONTACT ============ */
#s8{min-height:88vh}
.nc-contact{display:flex;flex-direction:column;gap:clamp(28px,6vh,64px)}
.nc-contact h2{font-family:var(--display);font-weight:800;font-size:clamp(2.4rem,9.5vw,8.4rem);line-height:.9;letter-spacing:-.03em;text-transform:uppercase}
.nc-contact h2 .nc-out{-webkit-text-stroke:1px var(--ink);color:transparent}
.nc-clinks{display:flex;flex-wrap:wrap;gap:clamp(28px,7vw,104px);align-items:flex-end}
.nc-clink{display:flex;flex-direction:column;gap:10px}
.nc-clink .nc-ck{font-family:var(--mono);font-size:11px;letter-spacing:.24em;color:var(--muted);text-transform:uppercase}
.nc-clink a{font-family:var(--display);font-weight:700;font-size:clamp(1.2rem,3.2vw,2.4rem);letter-spacing:-.01em;position:relative;width:max-content;transition:color .3s var(--ease)}
.nc-clink a::after{content:"";position:absolute;left:0;bottom:-4px;width:100%;height:1px;background:var(--accent-h);transform:scaleX(0);transform-origin:right;transition:transform .4s var(--ease)}
.nc-clink a:hover{color:var(--accent-h)}
.nc-clink a:hover::after{transform:scaleX(1);transform-origin:left}

footer{position:relative;z-index:1;border-top:1px solid var(--line);padding:28px clamp(18px,5vw,76px);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:var(--muted)}
footer .nc-fmark{display:flex;align-items:center;gap:12px;color:var(--ink2)}
footer .nc-fmark svg{width:18px;height:18px}
footer .nc-fmark .fm{fill:var(--ink2)}
footer .nc-fmark .fc{fill:var(--accent-h)}

@media(prefers-reduced-motion:reduce){
  *{animation:none!important;transition-duration:.01ms!important}
  .nc-reveal{opacity:1!important;transform:none!important}
}
</style>
</head>
<body>

<div class="nc-bg" aria-hidden="true">
  <canvas id="nc-canvas"></canvas>
  <div class="nc-smoke a"></div>
  <div class="nc-smoke b"></div>
  <div class="nc-smear"></div>
  <div class="nc-grid"></div>
  <div class="nc-vig"></div>
  <div class="nc-grain"></div>
</div>

<div class="nc-cursor" aria-hidden="true"><div class="nc-cring"></div><div class="nc-cdot"></div></div>
<div class="nc-prog" id="nc-prog"></div>

<header class="nc-top">
  <a href="#s1" class="nc-word" data-link>NOIA<b>·</b>CORE</a>
  <div class="nc-topright">
    <div class="nc-toggle" role="group" aria-label="Cosmología visual">
      <span class="nc-pill"></span>
      <button id="nc-noir" aria-pressed="true" data-link>NOIR</button>
      <button id="nc-blanc" aria-pressed="false" data-link>BLANC</button>
    </div>
    <div class="nc-clock"><span>UTC</span> <b id="nc-utc">--:--:--</b><br><span>41.38°N · STUDIO</span></div>
  </div>
</header>

<nav class="nc-index" aria-label="Secciones">
  <a href="#s1" data-i="s1"><span class="nc-il">Núcleo</span><span class="nc-id"></span></a>
  <a href="#s2" data-i="s2"><span class="nc-il">Doble lectura</span><span class="nc-id"></span></a>
  <a href="#s3" data-i="s3"><span class="nc-il">Armonía</span><span class="nc-id"></span></a>
  <a href="#s4" data-i="s4"><span class="nc-il">Capacidades</span><span class="nc-id"></span></a>
  <a href="#s5" data-i="s5"><span class="nc-il">Laboratorio</span><span class="nc-id"></span></a>
  <a href="#s6" data-i="s6"><span class="nc-il">Percepción</span><span class="nc-id"></span></a>
  <a href="#s7" data-i="s7"><span class="nc-il">Territorios</span><span class="nc-id"></span></a>
  <a href="#s8" data-i="s8"><span class="nc-il">Contacto</span><span class="nc-id"></span></a>
</nav>

<div id="nc-pre" aria-hidden="true">
  <svg width="78" height="78" viewBox="0 0 100 100" aria-hidden="true">
    <defs><radialGradient id="pg" cx="50%" cy="50%" r="50%"><stop offset="0%" stop-color="#fff"/><stop offset="100%" stop-color="var(--accent-h)"/></radialGradient></defs>
    <circle cx="50" cy="50" r="40" fill="none" stroke="var(--ink2)" stroke-width=".8" stroke-dasharray="80 120" style="transform-box:fill-box;transform-origin:center;animation:nc-spin 2.6s linear infinite"/>
    <circle cx="50" cy="50" r="28" fill="none" stroke="var(--muted)" stroke-width=".6" stroke-dasharray="6 12" style="transform-box:fill-box;transform-origin:center;animation:nc-spin 3.8s linear infinite reverse"/>
    <circle cx="50" cy="50" r="9" fill="url(#pg)" style="transform-box:fill-box;transform-origin:center;animation:nc-breathe 1.8s var(--ease) infinite"/>
  </svg>
  <div class="nc-pword" id="nc-pword"></div>
</div>

<main>

  <!-- S1 HERO -->
  <section id="s1">
    <div class="nc-beam"></div>
    <div class="nc-wrap nc-hero">
      <div class="nc-sidetext l nc-reveal"><span class="nc-idx">— 001</span>INTELIGENCIA<br>SILENCIOSA.<br>TECNOLOGÍA<br>ESENCIAL.</div>
      <div class="nc-sidetext r nc-reveal"><span class="nc-idx">MMXXVI —</span>ARQUITECTURA<br>DE INTELIGENCIA<br>PARA EL FUTURO<br>DE LO HUMANO.</div>

      <div class="nc-stage">
        <div class="nc-emblem-hero nc-orb nc-reveal" id="nc-emblem" data-magnetic>
          <svg viewBox="0 0 100 100" aria-label="Núcleo orbital NOIACORE">
            <defs>
              <radialGradient id="bloom" cx="50%" cy="50%" r="50%"><stop offset="0%" style="stop-color:var(--bloom)"/><stop offset="100%" stop-color="transparent"/></radialGradient>
              <linearGradient id="beamg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="transparent"/><stop offset="50%" style="stop-color:var(--beam)"/><stop offset="100%" stop-color="transparent"/></linearGradient>
            </defs>
            <line class="beam" x1="50" y1="2" x2="50" y2="98" stroke="url(#beamg)" stroke-width=".4"/>
            <ellipse class="ring r3" cx="50" cy="50" rx="46" ry="46"/>
            <ellipse class="ring r1" cx="50" cy="50" rx="38" ry="20" transform="rotate(28 50 50)"/>
            <ellipse class="ring r1" cx="50" cy="50" rx="38" ry="20" transform="rotate(-32 50 50)" style="animation-direction:reverse;animation-duration:38s"/>
            <ellipse class="ring r2" cx="50" cy="50" rx="30" ry="30"/>
            <g class="tick"><line x1="50" y1="6" x2="50" y2="11"/><line x1="50" y1="89" x2="50" y2="94"/><line x1="6" y1="50" x2="11" y2="50"/><line x1="89" y1="50" x2="94" y2="50"/></g>
            <circle cx="50" cy="50" r="22" fill="url(#bloom)"/>
            <g class="breathe">
              <circle class="core" cx="50" cy="50" r="9"/>
              <circle class="corec" cx="50" cy="50" r="3.4"/>
            </g>
          </svg>
        </div>
        <h1 class="nc-wordmark nc-reveal">NOIA<span class="nc-c">C</span>ORE</h1>
        <div class="nc-lab nc-reveal">LAB</div>
      </div>

      <div class="nc-floor" aria-hidden="true">
        <div class="nc-horizon"></div>
        <div class="nc-flare"></div>
        <div class="nc-ripple" style="width:30vw;height:30vw"></div>
        <div class="nc-ripple" style="width:48vw;height:48vw"></div>
        <div class="nc-ripple" style="width:70vw;height:70vw"></div>
      </div>
    </div>
    <div class="nc-scrollcue"><span>DESCENDER</span><span class="nc-bar"></span></div>
  </section>

  <!-- S2 DUAL READING -->
  <section id="s2">
    <div class="nc-wrap">
      <div class="nc-tag nc-reveal">002 — Doble lectura</div>
      <p class="nc-manifesto nc-reveal" id="nc-manifesto">Un mismo núcleo, <span class="nc-w red">dos</span> maneras de verlo. NOIR es gravedad: el núcleo como un sol que curva el silencio. BLANC es plano: el núcleo como un punto medido sobre el papel. Cambia la cosmología arriba y la marca entera cambia de lectura.</p>

      <div class="nc-dual nc-reveal">
        <figure class="nc-dnoir">
          <div class="nc-dorb nc-orb"><svg viewBox="0 0 100 100"><ellipse class="ring r1" cx="50" cy="50" rx="40" ry="22" transform="rotate(24 50 50)"/><ellipse class="ring r2" cx="50" cy="50" rx="30" ry="30"/><circle class="core" cx="50" cy="50" r="10"/><circle class="corec" cx="50" cy="50" r="3.6"/></svg></div>
          <div><h3><small>NOIR · GRAVITACIÓN</small>El silencio como materia.</h3><p>Masa negra, núcleo incandescente, anillos que orbitan. El cerebro lee profundidad, autoridad y misterio. La emoción contenida antes del movimiento.</p></div>
        </figure>
        <figure class="nc-dblanc">
          <div class="nc-dorb nc-orb"><svg viewBox="0 0 100 100"><ellipse class="ring r2" cx="50" cy="50" rx="42" ry="42"/><ellipse class="ring r2" cx="50" cy="50" rx="30" ry="30"/><ellipse class="ring r1" cx="50" cy="50" rx="20" ry="20"/><circle class="core" cx="50" cy="50" r="11"/><circle class="corec" cx="50" cy="50" r="4"/></svg></div>
          <div><h3><small>BLANC · MEDICIÓN</small>La lógica como trazo.</h3><p>Papel, líneas finas, núcleo azul frío. El cerebro lee precisión, método y claridad. El plano técnico de una inteligencia que se deja inspeccionar.</p></div>
        </figure>
      </div>
    </div>
  </section>

  <!-- S3 HARMONY -->
  <section id="s3">
    <div class="nc-wrap">
      <div class="nc-tag nc-reveal">003 — Teoría armónica</div>
      <div class="nc-harm-head nc-reveal">
        <h2>70 silencio · 20 tensión · 10 revelación.</h2>
        <p>Pasa sobre el 10 %. Es el único color que realmente importa: el que el ojo busca cuando ya no puede dejar de mirar.</p>
      </div>
      <div class="nc-prop nc-reveal" aria-label="Proporción cromática 70 20 10">
        <div class="nc-seg nc-s70">SILENCIO · 70</div>
        <div class="nc-seg nc-s20">TENSIÓN · 20</div>
        <div class="nc-seg nc-s10">10<span class="nc-reveal10">REVELACIÓN</span></div>
      </div>
      <div class="nc-chips nc-reveal">
        <div class="nc-chip"><div class="nc-sw" style="background:#050505"></div><div><h4>Negro</h4><div class="nc-hex">#050505</div><p>Ausencia de ruido. El silencio antes de la sinfonía.</p></div></div>
        <div class="nc-chip"><div class="nc-sw" style="background:#7A0E1A"></div><div><h4>Carmesí</h4><div class="nc-hex">#7A0E1A</div><p>Energía contenida. La firma. El 10 %.</p></div></div>
        <div class="nc-chip"><div class="nc-sw" style="background:#F4F4F2"></div><div><h4>Blanco</h4><div class="nc-hex">#F4F4F2</div><p>Información. Estructura. Lo que puede comprenderse.</p></div></div>
        <div class="nc-chip"><div class="nc-sw" style="background:#767676"></div><div><h4>Grafito</h4><div class="nc-hex">#767676</div><p>El puente. Tecnología sin futurismo barato.</p></div></div>
        <div class="nc-chip"><div class="nc-sw" style="background:linear-gradient(135deg,#3a2f12,#8a7332)"></div><div><h4>Oro</h4><div class="nc-hex">METAL</div><p>No lujo: legado. Lo que merece permanecer.</p></div></div>
      </div>
    </div>
  </section>

  <!-- S4 CAPABILITIES -->
  <section id="s4">
    <div class="nc-wrap">
      <div class="nc-tag nc-reveal">004 — Capacidades</div>
      <div class="nc-cap-intro nc-reveal">
        <h2>Capacidades, no servicios.</h2>
        <p>Cada línea es una pieza en exposición. Pasa por encima para leer lo que realmente hace.</p>
      </div>
      <div class="nc-caps nc-reveal" id="nc-caps">
