img,svg{display:block}

/* paper texture + gallery light (living, very quiet) */
.nc-tex{position:fixed;inset:0;z-index:0;pointer-events:none;background-image:var(--tex);background-size:cover;background-position:center;mix-blend-mode:multiply;opacity:.55}
.nc-light{position:fixed;inset:0;z-index:0;pointer-events:none;opacity:0;transition:opacity 1.2s var(--ease);
  background:radial-gradient(420px circle at var(--lx,50%) var(--ly,30%), rgba(122,14,26,.05), transparent 70%)}
.nc-light.on{opacity:1}

/* progress hairline */
.nc-prog{position:fixed;top:0;left:0;height:1.5px;width:100%;background:var(--accent);z-index:200;transform-origin:left center;transform:scaleX(0)}

/* ===== chrome ===== */
.nc-top{position:fixed;top:0;left:0;right:0;z-index:150;display:flex;justify-content:space-between;align-items:center;padding:22px clamp(20px,4.5vw,56px);transition:color .5s var(--ease);color:var(--ink)}
.nc-top.dark{color:var(--paper-on-dark)}
.nc-logo{font-family:var(--sans);font-weight:600;font-size:13px;letter-spacing:.34em;display:flex;align-items:center;gap:9px}
.nc-logo .nc-dot{width:6px;height:6px;background:var(--accent);display:inline-block}
.nc-topright{display:flex;align-items:center;gap:26px}
.nc-clock{font-family:var(--mono);font-size:10px;letter-spacing:.18em;opacity:.6}
.nc-navlink{font-family:var(--mono);font-size:11px;letter-spacing:.2em;text-transform:uppercase;position:relative;padding-bottom:3px}
.nc-navlink::after{content:"";position:absolute;left:0;bottom:0;width:100%;height:1px;background:currentColor;transform:scaleX(0);transform-origin:right;transition:transform .45s var(--ease)}
.nc-navlink:hover::after{transform:scaleX(1);transform-origin:left}
@media(max-width:680px){.nc-clock{display:none}}

/* index rail */
.nc-rail{position:fixed;right:clamp(16px,2.4vw,40px);top:50%;transform:translateY(-50%);z-index:140;display:flex;flex-direction:column;gap:15px;transition:color .5s var(--ease);color:var(--ink)}
.nc-rail.dark{color:var(--paper-on-dark)}
.nc-rail a{display:flex;align-items:center;justify-content:flex-end;gap:11px;font-family:var(--mono);font-size:9px;letter-spacing:.2em;opacity:.4;transition:opacity .4s var(--ease)}
.nc-rail a .nc-rl{opacity:0;transform:translateX(6px);transition:opacity .4s var(--ease),transform .4s var(--ease);white-space:nowrap}
.nc-rail a .nc-rd{width:14px;height:1px;background:currentColor;transition:width .4s var(--ease)}
.nc-rail a:hover{opacity:.85}
.nc-rail a:hover .nc-rl{opacity:1;transform:none}
.nc-rail a.on{opacity:1}
.nc-rail a.on .nc-rl{opacity:1;transform:none}
.nc-rail a.on .nc-rd{width:26px;background:var(--accent)}
@media(max-width:880px){.nc-rail{display:none}}

/* ===== layout ===== */
main{position:relative;z-index:1}
section{position:relative}
.nc-pad{padding-left:clamp(20px,5vw,76px);padding-right:clamp(20px,5vw,76px)}
.nc-wrap{width:100%;max-width:var(--maxw);margin:0 auto}
.nc-tag{font-family:var(--mono);font-size:11px;letter-spacing:.32em;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:14px}
.nc-tag::before{content:"";width:30px;height:1px;background:var(--accent)}
.nc-dark .nc-tag{color:var(--muted-on-dark)}

/* line reveal primitive (set visible by default; JS hides when animating) */
.ln{display:block;overflow:hidden;padding-bottom:.06em}
.ln>i{display:block;font-style:normal;will-change:transform}

/* ===== preloader ===== */
#nc-pre{position:fixed;inset:0;z-index:400;background:var(--paper);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:26px}
#nc-pre .nc-pbar{width:min(46vw,260px);height:1px;background:var(--line);position:relative;overflow:hidden}
#nc-pre .nc-pbar i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(0)}
#nc-pre .nc-pword{font-family:var(--sans);font-weight:600;font-size:12px;letter-spacing:.5em;color:var(--ink);opacity:0}

/* ===== S1 HERO ===== */
#s1{min-height:100vh;display:flex;flex-direction:column;justify-content:center;padding:clamp(120px,16vh,180px) 0 clamp(80px,12vh,140px)}
.nc-hero{display:flex;flex-direction:column;align-items:center;text-align:center;gap:clamp(26px,4vh,46px)}
.nc-kick{font-family:var(--mono);font-size:11px;letter-spacing:.4em;color:var(--muted);text-transform:uppercase}
.nc-emblem{width:clamp(140px,22vw,250px);aspect-ratio:1;color:var(--ink)}
.nc-emblem svg{width:100%;height:100%;overflow:visible}
.nc-emblem .mod{fill:none;stroke:currentColor;stroke-width:.9}
.nc-emblem .core{fill:var(--accent)}
.nc-wordmark{font-family:var(--sans);font-weight:500;font-size:clamp(2.4rem,9vw,7.4rem);letter-spacing:.3em;text-indent:.3em;line-height:1;color:var(--ink)}
.nc-tagline{font-family:var(--display);font-style:italic;font-weight:300;font-size:clamp(1.05rem,2.4vw,1.7rem);color:var(--ink-2);font-variation-settings:"opsz" 60,"wght" 300,"SOFT" 30;max-width:24ch}
.nc-scrollcue{position:absolute;left:50%;bottom:30px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:12px;font-family:var(--mono);font-size:10px;letter-spacing:.3em;color:var(--muted)}
.nc-scrollcue .nc-bar{width:1px;height:46px;background:linear-gradient(var(--accent),transparent);transform-origin:top;animation:nc-drip 2.6s var(--ease) infinite}
@keyframes nc-drip{0%{transform:scaleY(.15)}45%{transform:scaleY(1)}55%{transform:scaleY(1);transform-origin:bottom}100%{transform:scaleY(.15);transform-origin:bottom}}

/* ===== S2 MANIFESTO (dark, pinned) ===== */
#s2{background:var(--dark);color:var(--paper-on-dark)}
.nc-manifesto{height:100vh;display:flex;align-items:center}
.nc-mstage{position:relative;width:100%;height:60vh}
.nc-mslide{position:absolute;inset:0;display:flex;align-items:center;opacity:0;will-change:transform,opacity}
.nc-mslide p{font-family:var(--display);font-weight:300;line-height:1.06;letter-spacing:-.015em;font-size:clamp(1.9rem,6vw,5.4rem);max-width:16ch;font-variation-settings:"opsz" 144,"wght" 300,"SOFT" 20}
.nc-mslide p em{font-style:italic;color:var(--accent-h);font-variation-settings:"opsz" 144,"wght" 350}
.nc-mcount{position:absolute;right:0;bottom:-46px;font-family:var(--mono);font-size:11px;letter-spacing:.24em;color:var(--muted-on-dark)}

/* ===== S3 BUILD (pinned) ===== */
#s3{background:transparent}
.nc-build{height:100vh;display:flex;align-items:center}
.nc-bgrid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(30px,6vw,90px);align-items:center;width:100%}
.nc-bcopy .nc-tag{margin-bottom:34px}
.nc-bsteps{list-style:none;display:flex;flex-direction:column;gap:26px;margin-top:8px}
.nc-bstep{display:grid;grid-template-columns:46px 1fr;gap:18px;align-items:start;opacity:.28;transition:opacity .5s var(--ease)}
.nc-bstep.on{opacity:1}
.nc-bstep .nc-bn{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--accent);padding-top:5px}
.nc-bstep h3{font-family:var(--display);font-weight:400;font-size:clamp(1.3rem,2.6vw,2rem);letter-spacing:-.01em;line-height:1.1;font-variation-settings:"opsz" 48,"wght" 400}
.nc-bstep p{font-family:var(--sans);font-size:14px;color:var(--ink-2);margin-top:7px;max-width:34ch;line-height:1.55}
.nc-bvisual{display:flex;justify-content:center;align-items:center}
.nc-build-emblem{width:clamp(220px,30vw,420px);aspect-ratio:1;color:var(--ink)}
.nc-build-emblem svg{width:100%;height:100%;overflow:visible}
.nc-build-emblem .mod{fill:currentColor}
.nc-build-emblem .core{fill:var(--accent)}
@media(max-width:820px){
  .nc-bgrid{grid-template-columns:1fr;gap:40px}
  .nc-build{height:auto;padding:120px 0}
  .nc-bvisual{order:-1}
}

/* ===== S4 CAPABILITIES ===== */
#s4{padding:clamp(110px,16vh,180px) 0}
.nc-cap-head{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;flex-wrap:wrap;margin-bottom:clamp(40px,7vh,80px)}
.nc-cap-head h2{font-family:var(--display);font-weight:300;font-size:clamp(2.1rem,5.6vw,4.6rem);line-height:1;letter-spacing:-.02em;max-width:13ch;font-variation-settings:"opsz" 144,"wght" 300}
.nc-cap-head h2 em{font-style:italic;color:var(--accent)}
.nc-cap-head p{font-family:var(--mono);font-size:12px;letter-spacing:.08em;color:var(--muted);max-width:30ch;text-align:right}
.nc-caps{border-top:1px solid var(--line)}
.nc-cap{display:grid;grid-template-columns:64px 1fr auto;align-items:center;gap:clamp(14px,3vw,40px);padding:clamp(20px,3vh,34px) 4px;border-bottom:1px solid var(--line);transition:padding .5s var(--ease)}
.nc-cap .nc-cnum{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--muted)}
.nc-cap .nc-cname{font-family:var(--display);font-weight:400;font-size:clamp(1.4rem,3.4vw,2.7rem);letter-spacing:-.01em;line-height:1;color:var(--ink-2);transition:color .45s var(--ease),transform .45s var(--ease);font-variation-settings:"opsz" 48,"wght" 400}
.nc-cap .nc-cgloss{font-family:var(--mono);font-size:12px;letter-spacing:.04em;color:var(--muted);opacity:0;transform:translateX(-8px);transition:opacity .45s var(--ease),transform .45s var(--ease)}
.nc-cap .nc-carrow{font-family:var(--mono);color:var(--accent);opacity:0;transform:translateX(-8px);transition:opacity .45s var(--ease),transform .45s var(--ease)}
.nc-cap:hover{padding-left:clamp(20px,3vw,40px)}
.nc-cap:hover .nc-cname{color:var(--ink);transform:translateX(6px)}
.nc-cap:hover .nc-cgloss,.nc-cap:hover .nc-carrow{opacity:1;transform:none}
@media(max-width:760px){.nc-cap{grid-template-columns:46px 1fr}.nc-cap .nc-cgloss,.nc-cap .nc-carrow{display:none}}

/* ===== S5 METRICS ===== */
#s5{padding:clamp(110px,16vh,180px) 0;background:var(--paper-2)}
.nc-met-head{margin-bottom:clamp(46px,8vh,90px);max-width:18ch}
.nc-met-head h2{font-family:var(--display);font-weight:300;font-size:clamp(2rem,5.4vw,4.4rem);line-height:1.02;letter-spacing:-.02em;font-variation-settings:"opsz" 144,"wght" 300}
.nc-met-head h2 em{font-style:italic;color:var(--accent)}
.nc-mets{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.nc-met{background:var(--paper-2);padding:clamp(28px,4vw,52px) clamp(20px,2.4vw,34px);display:flex;flex-direction:column;gap:18px;min-height:230px;justify-content:space-between}
.nc-met .nc-mval{font-family:var(--display);font-weight:300;font-size:clamp(2.6rem,6vw,5rem);line-height:.9;letter-spacing:-.03em;font-variation-settings:"opsz" 144,"wght" 300}
.nc-met .nc-mval .nc-msuf{color:var(--accent);font-size:.5em;vertical-align:super;margin-left:.05em}
.nc-met .nc-mk{font-family:var(--mono);font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:var(--muted)}
.nc-met .nc-md{font-family:var(--sans);font-size:13.5px;color:var(--ink-2);line-height:1.5}
@media(max-width:880px){.nc-mets{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.nc-mets{grid-template-columns:1fr}}

/* ===== S6 PERCEPTION ===== */
#s6{padding:clamp(110px,16vh,180px) 0}
.nc-perc-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(30px,6vw,90px);align-items:center;margin-top:clamp(40px,7vh,80px)}
.nc-perc-copy h2{font-family:var(--display);font-weight:300;font-size:clamp(2rem,5.4vw,4.4rem);line-height:1;letter-spacing:-.02em;font-variation-settings:"opsz" 144,"wght" 300}
.nc-perc-copy h2 em{font-style:italic;color:var(--accent)}
.nc-perc-copy p{font-family:var(--sans);font-size:clamp(1rem,1.4vw,1.15rem);color:var(--ink-2);margin-top:24px;max-width:42ch;line-height:1.6}
.nc-perc-copy .nc-pk{font-family:var(--mono);font-size:11px;letter-spacing:.26em;color:var(--accent);text-transform:uppercase;margin-bottom:24px;display:block}
.nc-rubin{position:relative;aspect-ratio:1;border:1px solid var(--line);overflow:hidden;background:var(--paper)}
.nc-rubin svg{position:absolute;inset:0;width:100%;height:100%}
.nc-rubin .nc-rlayer{position:absolute;inset:0}
.nc-rubin .nc-rb{fill:var(--ink)}
.nc-rubin .nc-rp{fill:var(--paper)}
.nc-rubin-cap{font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--muted);margin-top:18px;text-align:center}
@media(max-width:820px){.nc-perc-grid{grid-template-columns:1fr}}

/* ===== S7 CONTACT (dark) ===== */
#s7{background:var(--dark);color:var(--paper-on-dark);padding:clamp(120px,18vh,200px) 0 clamp(70px,10vh,120px)}
.nc-contact{display:flex;flex-direction:column;gap:clamp(34px,6vh,70px)}
.nc-contact .nc-ctag{font-family:var(--mono);font-size:11px;letter-spacing:.32em;color:var(--muted-on-dark);text-transform:uppercase;display:flex;align-items:center;gap:14px}
.nc-contact .nc-ctag::before{content:"";width:30px;height:1px;background:var(--accent)}
.nc-contact h2{font-family:var(--display);font-weight:300;font-size:clamp(2.8rem,11vw,9.5rem);line-height:.92;letter-spacing:-.03em;font-variation-settings:"opsz" 144,"wght" 300}
.nc-contact h2 em{font-style:italic;color:var(--accent-h)}
.nc-clinks{display:flex;flex-wrap:wrap;gap:clamp(34px,8vw,120px);align-items:flex-end}
.nc-clink{display:flex;flex-direction:column;gap:12px}
.nc-clink .nc-ck{font-family:var(--mono);font-size:11px;letter-spacing:.24em;color:var(--muted-on-dark);text-transform:uppercase}
.nc-clink a{font-family:var(--display);font-weight:400;font-size:clamp(1.3rem,3.4vw,2.6rem);letter-spacing:-.01em;position:relative;width:max-content;font-variation-settings:"opsz" 48,"wght" 400;transition:color .4s var(--ease)}
.nc-clink a::after{content:"";position:absolute;left:0;bottom:-3px;width:100%;height:1px;background:var(--accent-h);transform:scaleX(0);transform-origin:right;transition:transform .5s var(--ease)}
.nc-clink a:hover{color:var(--accent-h)}
.nc-clink a:hover::after{transform:scaleX(1);transform-origin:left}

footer{position:relative;z-index:1;background:var(--dark);color:var(--muted-on-dark);border-top:1px solid var(--line-on-dark);padding:26px clamp(20px,5vw,76px);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;font-family:var(--mono);font-size:10px;letter-spacing:.2em}
footer .nc-fmark{display:flex;align-items:center;gap:11px;color:var(--paper-on-dark)}
footer .nc-fmark svg{width:16px;height:16px}
footer .nc-fmark .fm{fill:var(--paper-on-dark)}
footer .nc-fmark .fc{fill:var(--accent-h)}

@media(prefers-reduced-motion:reduce){
  .nc-scrollcue .nc-bar{animation:none}
}
</style>
</head>
<body>

<div class="nc-tex" aria-hidden="true"></div>
<div class="nc-light" id="ncLight" aria-hidden="true"></div>
<div class="nc-prog" id="ncProg" aria-hidden="true"></div>

<header class="nc-top" id="ncTop">
  <a href="#s1" class="nc-logo"><span class="nc-dot"></span>NOIACORE</a>
  <div class="nc-topright">
    <span class="nc-clock" id="ncClock">--:--</span>
    <a href="#s7" class="nc-navlink">Contacto</a>
  </div>
</header>

<nav class="nc-rail" id="ncRail" aria-label="Secciones">
  <a href="#s1" data-i="s1"><span class="nc-rl">Núcleo</span><span class="nc-rd"></span></a>
  <a href="#s2" data-i="s2"><span class="nc-rl">Manifiesto</span><span class="nc-rd"></span></a>
  <a href="#s3" data-i="s3"><span class="nc-rl">Construcción</span><span class="nc-rd"></span></a>
  <a href="#s4" data-i="s4"><span class="nc-rl">Capacidades</span><span class="nc-rd"></span></a>
  <a href="#s5" data-i="s5"><span class="nc-rl">Señal</span><span class="nc-rd"></span></a>
  <a href="#s6" data-i="s6"><span class="nc-rl">Percepción</span><span class="nc-rd"></span></a>
  <a href="#s7" data-i="s7"><span class="nc-rl">Contacto</span><span class="nc-rd"></span></a>
</nav>

<div id="nc-pre" aria-hidden="true">
  <div class="nc-pbar"><i id="ncPbar"></i></div>
  <div class="nc-pword" id="ncPword">NOIACORE</div>
</div>

<main>

  <!-- S1 HERO -->
  <section id="s1">
    <div class="nc-pad">
      <div class="nc-wrap nc-hero">
        <div class="nc-kick ln"><i>Cognitive Systems Studio · MMXXVI</i></div>
        <div class="nc-emblem" id="ncEmblem" aria-label="Glifo NOIACORE"></div>
        <h1 class="nc-wordmark ln"><i>NOIACORE</i></h1>
        <p class="nc-tagline ln"><i>Inteligencia que se diseña.</i></p>
      </div>
    </div>
    <div class="nc-scrollcue" id="ncCue"><span>DESCENDER</span><span class="nc-bar"></span></div>
  </section>

  <!-- S2 MANIFESTO -->
  <section id="s2" class="nc-dark">
    <div class="nc-pad">
      <div class="nc-wrap">
        <div class="nc-manifesto">
          <div style="width:100%">
            <div class="nc-tag" style="margin-bottom:40px">001 — Manifiesto</div>
            <div class="nc-mstage" id="ncMstage">
              <div class="nc-mslide"><p>El color no decora. El color <em>piensa</em>.</p></div>
              <div class="nc-mslide"><p>Cada tono es un <em>estado mental</em>, no una superficie.</p></div>
              <div class="nc-mslide"><p>No buscamos que digas «qué bonito». Buscamos que <em>no puedas dejar de mirar</em>.</p></div>
            </div>
            <div class="nc-mcount" id="ncMcount">01 / 03</div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- S3 BUILD -->
  <section id="s3">
    <div class="nc-pad">
      <div class="nc-wrap">
        <div class="nc-build">
          <div class="nc-bgrid">
            <div class="nc-bcopy">
              <div class="nc-tag">002 — Se construye</div>
              <ul class="nc-bsteps" id="ncBsteps">
                <li class="nc-bstep on" data-step="0"><span class="nc-bn">01</span><div><h3>Silencio.</h3><p>Grandes masas vacías. El negro y el papel eliminan el ruido. El cerebro descansa y presta atención.</p></div></li>
                <li class="nc-bstep" data-step="1"><span class="nc-bn">02</span><div><h3>Tensión.</h3><p>La estructura aparece módulo a módulo. Geometría exacta, nada decorativo. Todo responde a una función.</p></div></li>
                <li class="nc-bstep" data-step="2"><span class="nc-bn">03</span><div><h3>Revelación.</h3><p>Un único punto carmesí enciende el núcleo. El 10 % que el ojo busca cuando ya no puede dejar de mirar.</p></div></li>
              </ul>
            </div>
            <div class="nc-bvisual">
              <div class="nc-build-emblem" id="ncBuildEmblem" aria-label="Glifo ensamblándose"></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- S4 CAPABILITIES -->
  <section id="s4">
    <div class="nc-pad">
      <div class="nc-wrap">
        <div class="nc-cap-head">
          <h2 class="ln"><i>Capacidades,</i></h2>
          <h2 class="ln"><i>no <em>servicios</em>.</i></h2>
          <p style="grid-column:1/-1;text-align:left;max-width:46ch;margin-top:6px">Cada línea es una pieza en exposición. Pasa por encima para leer lo que realmente hace.</p>
        </div>
        <div class="nc-caps" id="ncCaps">
          <a class="nc-cap" href="#s7"><span class="nc-cnum">01</span><span class="nc-cname">Intelligence Architecture</span><span class="nc-cgloss">Diseñamos cómo piensa tu sistema.</span><span class="nc-carrow">→</span></a>
          <a class="nc-cap" href="#s7"><span class="nc-cnum">02</span><span class="nc-cname">Business Automation</span><span class="nc-cgloss">El trabajo repetitivo deja de existir.</span><span class="nc-carrow">→</span></a>
          <a class="nc-cap" href="#s7"><span class="nc-cnum">03</span><span class="nc-cname">AI Systems</span><span class="nc-cgloss">Modelos que trabajan mientras duermes.</span><span class="nc-carrow">→</span></a>
          <a class="nc-cap" href="#s7"><span class="nc-cnum">04</span><span class="nc-cname">Cognitive Design</span><span class="nc-cgloss">Interfaces que el cerebro entiende solo.</span><span class="nc-carrow">→</span></a>
          <a class="nc-cap" href="#s7"><span class="nc-cnum">05</span><span class="nc-cname">Decision Systems</span><span class="nc-cgloss">Menos intuición, más señal.</span><span class="nc-carrow">→</span></a>
          <a class="nc-cap" href="#s7"><span class="nc-cnum">06</span><span class="nc-cname">Agent Engineering</span><span class="nc-cgloss">Agentes con criterio, no con scripts.</span><span class="nc-carrow">→</span></a>
