<script>
(function(){
  "use strict";
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var fine = window.matchMedia("(hover: hover)").matches;
  var SVGNS = "http://www.w3.org/2000/svg";

  /* glyph module coordinates (viewBox 0 0 100 100, module 12x12) */
  var MODULES = [
    [44,26],[62,44],[44,62],[26,44],                 /* inner ring */
    [26,8],[44,8],[62,8],[80,26],[80,44],[80,62],     /* outer spiral (open) */
    [62,80],[44,80],[26,80],[8,62],[8,44],
    [8,8]                                             /* detached = learning */
  ];
  var CORE = {x:40,y:40,s:20};

  function el(tag,attrs){ var e=document.createElementNS(SVGNS,tag); for(var k in attrs){ e.setAttribute(k,attrs[k]); } return e; }

  /* ---- build hero glyph (draw-on) ---- */
  (function(){
    var host = document.getElementById("ncEmblem");
    var svg = el("svg",{viewBox:"0 0 100 100"});
    MODULES.forEach(function(m){
      var r = el("rect",{x:m[0],y:m[1],width:12,height:12,class:"mod",pathLength:"1"});
      r.style.strokeDasharray = "1";
      r.style.strokeDashoffset = reduce ? "0" : "1";
      r.style.fill = "transparent";
      svg.appendChild(r);
    });
    var c = el("rect",{x:CORE.x,y:CORE.y,width:CORE.s,height:CORE.s,class:"core"});
    c.style.transformBox = "fill-box"; c.style.transformOrigin = "center";
    if(!reduce){ c.style.transform = "scale(0)"; c.style.opacity = "0"; }
    svg.appendChild(c);
    host.appendChild(svg);
    host._mods = svg.querySelectorAll(".mod");
    host._core = c;
  })();

  /* ---- build assembly glyph (scrub) ---- */
  (function(){
    var host = document.getElementById("ncBuildEmblem");
    var svg = el("svg",{viewBox:"0 0 100 100"});
    var rects = [];
    MODULES.forEach(function(m){
      var r = el("rect",{x:m[0],y:m[1],width:12,height:12,class:"mod"});
      r.style.transformBox = "fill-box"; r.style.transformOrigin = "center";
      svg.appendChild(r); rects.push(r);
    });
    var c = el("rect",{x:CORE.x,y:CORE.y,width:CORE.s,height:CORE.s,class:"core"});
    c.style.transformBox = "fill-box"; c.style.transformOrigin = "center";
    svg.appendChild(c);
    host.appendChild(svg);
    host._mods = rects; host._core = c;
  })();

  /* ===================== GSAP ===================== */
  if(window.gsap && window.ScrollTrigger){
    gsap.registerPlugin(ScrollTrigger);

    /* progress bar */
    gsap.to("#ncProg",{scaleX:1,ease:"none",scrollTrigger:{trigger:document.body,start:"top top",end:"bottom bottom",scrub:.3}});

    if(!reduce){

      /* ---------- PRELOADER ---------- */
      var preTl = gsap.timeline({onComplete:function(){
        gsap.to("#nc-pre",{opacity:0,duration:.7,ease:"power2.inOut",onComplete:function(){ document.getElementById("nc-pre").style.display="none"; heroIn(); }});
      }});
      preTl.to("#ncPbar",{scaleX:1,duration:1.1,ease:"power2.inOut"})
           .to("#ncPword",{opacity:1,duration:.5},"-=.4")
           .to({}, {duration:.35});

      /* ---------- HERO entrance ---------- */
      function heroIn(){
        var emblem = document.getElementById("ncEmblem");
        var tl = gsap.timeline();
        tl.to(emblem._mods,{strokeDashoffset:0,duration:.9,stagger:.045,ease:"power2.out"})
          .to(emblem._mods,{fill:"currentColor",duration:.6,stagger:.03},"-=.4")
          .to(emblem._core,{scale:1,opacity:1,duration:.7,ease:"back.out(1.6)"},"-=.3");
        gsap.utils.toArray("#s1 .ln>i").forEach(function(node,i){
          gsap.fromTo(node,{yPercent:115},{yPercent:0,duration:1,ease:"expo.out",delay:.15+i*.09});
        });
        gsap.from("#ncCue",{opacity:0,y:14,duration:.8,delay:1.1});
      }

      /* hero parallax on scroll */
      gsap.to("#ncEmblem",{yPercent:-22,ease:"none",scrollTrigger:{trigger:"#s1",start:"top top",end:"bottom top",scrub:true}});
      gsap.to("#s1 .nc-wordmark",{yPercent:-12,ease:"none",scrollTrigger:{trigger:"#s1",start:"top top",end:"bottom top",scrub:true}});
      gsap.to("#ncCue",{opacity:0,ease:"none",scrollTrigger:{trigger:"#s1",start:"top top",end:"30% top",scrub:true}});

      /* ---------- generic line reveals ---------- */
      gsap.utils.toArray(".ln>i").forEach(function(node){
        if(node.closest("#s1")) return;
        gsap.fromTo(node,{yPercent:115},{yPercent:0,duration:1,ease:"expo.out",scrollTrigger:{trigger:node,start:"top 88%",toggleActions:"play none none reverse"}});
      });

      /* ---------- S2 MANIFESTO pinned crossfade ---------- */
      var slides = gsap.utils.toArray(".nc-mslide");
      var mcount = document.getElementById("ncMcount");
      var mTl = gsap.timeline({scrollTrigger:{trigger:"#s2",start:"top top",end:"+=220%",pin:".nc-manifesto",scrub:.6}});
      gsap.set(slides[0],{opacity:1});
      for(var i=0;i<slides.length;i++){
        (function(idx){
          var seg = idx/(slides.length);
          if(idx>0){
            mTl.fromTo(slides[idx],{opacity:0,yPercent:40},{opacity:1,yPercent:0,duration:.5,ease:"power2.out"},seg)
               .call(function(){ mcount.textContent = "0"+(idx+1)+" / 0"+slides.length; },null,seg+.02);
          }
          if(idx<slides.length-1){
            mTl.to(slides[idx],{opacity:0,yPercent:-40,duration:.5,ease:"power2.in"},seg+.5);
          }
        })(i);
      }

      /* ---------- S3 BUILD pinned assembly ---------- */
      var bEmblem = document.getElementById("ncBuildEmblem");
      var steps = gsap.utils.toArray(".nc-bstep");
      gsap.set(bEmblem._mods,{opacity:0,scale:.2,x:function(idx){ var m=MODULES[idx]; return (44-m[0]); },y:function(idx){ var m=MODULES[idx]; return (44-m[1]); }});
      gsap.set(bEmblem._core,{opacity:0,scale:0});
      var bTl = gsap.timeline({scrollTrigger:{trigger:"#s3",start:"top top",end:"+=190%",pin:".nc-build",scrub:.7,
        onEnter:function(){setDark(false);}, onLeaveBack:function(){setDark(false);} }});
      /* step 1 -> silence: faint outline hint (we keep empty, just activate label) */
      bTl.call(function(){setStep(0);},null,0.02);
      /* step 2 -> tension: modules fly in from center, staggered */
      bTl.to(bEmblem._mods,{opacity:1,scale:1,x:0,y:0,duration:1,stagger:.05,ease:"power3.out"},0.18);
      bTl.call(function(){setStep(1);},null,0.2);
      /* step 3 -> revelation: core ignites */
      bTl.to(bEmblem._core,{opacity:1,scale:1,duration:.8,ease:"back.out(1.7)"},0.78);
      bTl.call(function(){setStep(2);},null,0.78);

      function setStep(n){ steps.forEach(function(s,i){ s.classList.toggle("on", i<=n); }); }

      /* ---------- S4 capabilities stagger ---------- */
      gsap.from("#ncCaps .nc-cap",{opacity:0,y:26,duration:.8,stagger:.07,ease:"power3.out",scrollTrigger:{trigger:"#ncCaps",start:"top 80%"}});

      /* ---------- S5 count up ---------- */
      document.querySelectorAll(".nc-count").forEach(function(node){
        var to = parseFloat(node.getAttribute("data-to"));
        var dec = parseInt(node.getAttribute("data-dec")||"0",10);
        var obj = {v:0};
        gsap.to(obj,{v:to,duration:1.6,ease:"power2.out",scrollTrigger:{trigger:node,start:"top 88%"},onUpdate:function(){ node.textContent = dec?obj.v.toFixed(dec):Math.round(obj.v); }});
      });
      gsap.from("#ncMets .nc-met",{opacity:0,y:30,duration:.8,stagger:.08,ease:"power3.out",scrollTrigger:{trigger:"#ncMets",start:"top 82%"}});

      /* ---------- S6 rubin invert on scrub ---------- */
      gsap.to("#ncRubinB",{opacity:1,ease:"none",scrollTrigger:{trigger:"#ncRubin",start:"top 70%",end:"bottom 35%",scrub:.5,
        onUpdate:function(self){ document.getElementById("ncRubinCap").textContent = self.progress>0.5 ? "Ahora el fondo es figura: aparecen dos rostros mirándose." : "Un jarrón. O dos rostros de perfil. Nunca ambos a la vez."; }}});

      /* ---------- S7 contact reveal ---------- */
      gsap.from("#s7 .nc-clinks > *",{opacity:0,y:24,duration:.8,stagger:.12,ease:"power3.out",scrollTrigger:{trigger:"#s7 .nc-clinks",start:"top 85%"}});

    } else {
      /* reduced motion: everything visible */
      document.getElementById("nc-pre").style.display="none";
      document.querySelectorAll(".nc-mslide").forEach(function(s,i){ s.style.opacity = i===0?1:0; });
      var bE=document.getElementById("ncBuildEmblem");
      gsap.set(bE._mods,{opacity:1}); gsap.set(bE._core,{opacity:1});
    }

    /* ---------- dark-section chrome toggle ---------- */
    function setDark(on){
      document.getElementById("ncTop").classList.toggle("dark",on);
      document.getElementById("ncRail").classList.toggle("dark",on);
    }
    ["#s2","#s7"].forEach(function(sel){
      ScrollTrigger.create({trigger:sel,start:"top 60px",end:"bottom 60px",onToggle:function(self){ setDark(self.isActive); }});
    });

    /* ---------- rail active state ---------- */
    document.querySelectorAll("section[id]").forEach(function(sec){
      ScrollTrigger.create({trigger:sec,start:"top center",end:"bottom center",onToggle:function(self){
        if(self.isActive){
          document.querySelectorAll(".nc-rail a").forEach(function(a){ a.classList.toggle("on", a.getAttribute("data-i")===sec.id); });
        }
      }});
    });

  } else {
    document.getElementById("nc-pre").style.display="none";
  }

  /* ===================== ambient: gallery light + clock ===================== */
  var light = document.getElementById("ncLight");
  if(fine && !reduce){
    var lx=50,ly=30,tx=50,ty=30;
    window.addEventListener("mousemove",function(e){ tx=e.clientX/innerWidth*100; ty=e.clientY/innerHeight*100; light.classList.add("on"); });
    (function lp(){ lx+=(tx-lx)*.06; ly+=(ty-ly)*.06; light.style.setProperty("--lx",lx+"%"); light.style.setProperty("--ly",ly+"%"); requestAnimationFrame(lp); })();
  }
  function tick(){ var d=new Date(); function p(n){return (n<10?"0":"")+n;} var c=document.getElementById("ncClock"); if(c) c.textContent=p(d.getUTCHours())+":"+p(d.getUTCMinutes())+" UTC"; }
  tick(); setInterval(tick,1000);

  /* smooth anchor */
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener("click",function(e){
      var id=a.getAttribute("href"); if(id.length<2) return;
      var t=document.querySelector(id); if(!t) return;
      e.preventDefault(); window.scrollTo({top:t.offsetTop,behavior:reduce?"auto":"smooth"});
    });
  });

})();
</script>
</body>
</html>
