<script>
(function(){
  "use strict";
  var reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var fine = window.matchMedia("(hover: hover)").matches;
  var NS = "http://www.w3.org/2000/svg";

  /* glyph modules (viewBox 100) */
  var MODS = [
    [44,26],[62,44],[44,62],[26,44],
    [26,8],[44,8],[62,8],[80,26],[80,44],[80,62],
    [62,80],[44,80],[26,80],[8,62],[8,44],
    [8,8]
  ];
  var CORE = {x:40,y:40,s:20};
  function mk(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}

  /* build assembly glyph */
  (function(){
    var host=document.getElementById("ncBemblem");
    var svg=mk("svg",{viewBox:"0 0 100 100"});
    var rects=[];
    MODS.forEach(function(m,i){
      var r=mk("rect",{x:m[0],y:m[1],width:12,height:12,class:"mod"+(i%3===2?" dim":"")});
      r.style.transformBox="fill-box";r.style.transformOrigin="center";
      svg.appendChild(r);rects.push(r);
    });
    var c=mk("rect",{x:CORE.x,y:CORE.y,width:CORE.s,height:CORE.s,class:"core"});
    c.style.transformBox="fill-box";c.style.transformOrigin="center";
    svg.appendChild(c);
    host.appendChild(svg);
    host._mods=rects;host._core=c;
  })();

  /* vertical ticks */
  var SECS=["s0","s1","s2","s3","s4","s5","s6"];
  (function(){
    var t=document.getElementById("ncTicks");
    SECS.forEach(function(id){
      var a=document.createElement("a");a.href="#"+id;a.setAttribute("data-i",id);
      var d=document.createElement("span");d.className="nc-tk";a.appendChild(d);
      a.style.top="0"; /* positioned via flex parent trick: we instead place absolutely */
      t.appendChild(a);
    });
    /* position ticks evenly */
    var nodes=t.querySelectorAll("a");
    nodes.forEach(function(a,i){ a.style.top=(i/(SECS.length-1)*100)+"%"; });
    nodes.forEach(function(a){
      a.addEventListener("click",function(e){
        var el=document.getElementById(a.getAttribute("data-i"));
        if(el){e.preventDefault();window.scrollTo({top:el.offsetTop,behavior:reduce?"auto":"smooth"});}
      });
    });
  })();

  var G = window.gsap, ST = window.ScrollTrigger;

  if(G && ST){
    G.registerPlugin(ST);

    /* progress fill */
    G.to("#ncFill",{scaleY:1,ease:"none",scrollTrigger:{trigger:document.body,start:"top top",end:"bottom bottom",scrub:.3}});

    if(!reduce){

      /* ---------- PRELOADER ---------- */
      var pre=G.timeline({onComplete:function(){
        G.to("#nc-pre",{opacity:0,duration:.7,ease:"power2.inOut",onComplete:function(){document.getElementById("nc-pre").style.display="none";heroIn();}});
      }});
      pre.to("#ncPbar",{scaleX:1,duration:1.05,ease:"power2.inOut"})
         .to("#ncPword",{opacity:1,duration:.45},"-=.35")
         .to({},{duration:.3});

      /* ---------- HERO IN ---------- */
      function heroIn(){
        var rings=["#emHalo","#emR1","#emR2","#emR3"];
        rings.forEach(function(s){var n=document.querySelector(s);n.style.strokeDasharray="1";n.style.strokeDashoffset="1";});
        var core=document.getElementById("emCore");
        G.set(core,{transformOrigin:"center",scale:0,opacity:0});
        var tl=G.timeline();
        tl.to(rings.map(function(s){return s;}),{strokeDashoffset:0,duration:1.1,stagger:.12,ease:"power2.inOut"})
          .to(core,{scale:1,opacity:1,duration:.7,ease:"back.out(1.7)"},"-=.4");
        G.utils.toArray("#s0 .ln>i").forEach(function(n,i){
          G.fromTo(n,{yPercent:115},{yPercent:0,duration:1.1,ease:"expo.out",delay:.2+i*.1});
        });
        G.to(["#hudTL","#hudTR","#hudBL"],{opacity:1,duration:.9,stagger:.08,delay:.5});
        G.to("#ncCue",{opacity:1,duration:.8,delay:1.1});
      }

      /* hero parallax */
      G.to("#ncEmblem",{yPercent:-34,ease:"none",scrollTrigger:{trigger:"#s0",start:"top top",end:"bottom top",scrub:true}});
      G.to("#s0 .nc-word",{yPercent:-16,ease:"none",scrollTrigger:{trigger:"#s0",start:"top top",end:"bottom top",scrub:true}});
      G.to(["#hudTL","#hudTR","#hudBL","#ncCue"],{opacity:0,ease:"none",scrollTrigger:{trigger:"#s0",start:"top top",end:"40% top",scrub:true}});

      /* ---------- rules grow ---------- */
      G.utils.toArray("[data-rule]").forEach(function(r){
        G.to(r,{scaleX:1,duration:1,ease:"power3.inOut",scrollTrigger:{trigger:r,start:"top 90%"}});
      });

      /* ---------- generic line reveals ---------- */
      G.utils.toArray(".ln>i").forEach(function(n){
        if(n.closest("#s0"))return;
        G.fromTo(n,{yPercent:115},{yPercent:0,duration:1.05,ease:"expo.out",scrollTrigger:{trigger:n,start:"top 88%",toggleActions:"play none none reverse"}});
      });

      /* ---------- S1 BUILD pinned assembly ---------- */
      var bE=document.getElementById("ncBemblem");
      var phrases=G.utils.toArray(".nc-bphrase");
      var steps=G.utils.toArray("#ncBsteps li");
      G.set(bE._mods,{opacity:0,scale:.15,x:function(i){return (50-(MODS[i][0]+6));},y:function(i){return (50-(MODS[i][1]+6));}});
      G.set(bE._core,{opacity:0,scale:0});
      G.set(phrases[0],{opacity:1});

      var bTl=G.timeline({scrollTrigger:{trigger:"#s1",start:"top top",end:"+=200%",pin:".nc-build",scrub:.7,anticipatePin:1}});

      /* phase 1 -> 2 : structure flies in */
      bTl.to(bE._mods,{opacity:1,scale:1,x:0,y:0,duration:1,stagger:.04,ease:"power3.out"},0.30);
      bTl.to(phrases[0],{opacity:0,yPercent:-50,duration:.4,ease:"power2.in"},0.30);
      bTl.fromTo(phrases[1],{opacity:0,yPercent:50},{opacity:1,yPercent:0,duration:.4,ease:"power2.out"},0.34);
      bTl.call(function(){steps.forEach(function(s,i){s.classList.toggle("on",i<=1);});},null,0.34);

      /* phase 2 -> 3 : core ignites */
      bTl.to(bE._core,{opacity:1,scale:1,duration:.7,ease:"back.out(1.7)"},0.74);
      bTl.to(phrases[1],{opacity:0,yPercent:-50,duration:.4,ease:"power2.in"},0.74);
      bTl.fromTo(phrases[2],{opacity:0,yPercent:50},{opacity:1,yPercent:0,duration:.4,ease:"power2.out"},0.78);
      bTl.call(function(){steps.forEach(function(s,i){s.classList.toggle("on",i<=2);});},null,0.78);

      /* ---------- S2 manifesto word light (scrub) ---------- */
      var man=document.getElementById("ncMan");
      man.innerHTML=man.innerHTML.replace(/>([^<]+)</g,function(m,txt){
        return ">"+txt.split(/(\s+)/).map(function(w){
          if(/^\s+$/.test(w))return w;
          if(/^<span/.test(w))return w;
          return '<span class="w">'+w+'</span>';
        }).join("")+"<";
      });
      /* keep the red span intact: re-mark */
      var mwords=Array.prototype.slice.call(man.querySelectorAll(".w"));
      ST.create({trigger:"#s2",start:"top 75%",end:"bottom 60%",scrub:.4,onUpdate:function(self){
        var n=Math.floor(self.progress*mwords.length);
        mwords.forEach(function(w,i){w.classList.toggle("lit",i<n);});
      }});

      /* ---------- S3 capabilities stagger ---------- */
      G.from("#ncCaps .nc-cap",{opacity:0,y:24,duration:.8,stagger:.06,ease:"power3.out",scrollTrigger:{trigger:"#ncCaps",start:"top 82%"}});

      /* ---------- S4 count up ---------- */
      function countUp(node){
        var to=parseFloat(node.getAttribute("data-to"));
        var dec=parseInt(node.getAttribute("data-dec")||"0",10);
        var o={v:0};
        G.to(o,{v:to,duration:1.6,ease:"power2.out",scrollTrigger:{trigger:node,start:"top 88%"},onUpdate:function(){node.textContent=dec?o.v.toFixed(dec):Math.round(o.v);}});
      }
      countUp(document.getElementById("ncBig"));
      document.querySelectorAll(".nc-count").forEach(countUp);
      G.from("#ncMets .nc-met",{opacity:0,y:30,duration:.8,stagger:.08,ease:"power3.out",scrollTrigger:{trigger:"#ncMets",start:"top 84%"}});

      /* ---------- S5 rubin invert (scrub) ---------- */
      G.to("#ncRubinB",{opacity:1,ease:"none",scrollTrigger:{trigger:"#ncRubin",start:"top 72%",end:"bottom 38%",scrub:.5,onUpdate:function(self){
