      }}});

      /* ---------- S6 contact reveal ---------- */
      G.from("#s6 .nc-clinks > *",{opacity:0,y:24,duration:.8,stagger:.12,ease:"power3.out",scrollTrigger:{trigger:"#s6 .nc-clinks",start:"top 86%"}});

    } else {
      document.getElementById("nc-pre").style.display="none";
      var bE2=document.getElementById("ncBemblem");
